insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "762fdb8f-4973-499c-8c08-224ca00f3095", "episode_id": "8d72a24e-5891-43be-b320-ead7f102ad1d", "cms_item_id": "68225dfc7bb476527f8c4878", "chunk_index": 15, "content": "Darren Kinnaird (40:54): Yeah, I mean I think, again, I'll go back to this. I think I sent you a note before the show of everything has changed and nothing's changed. Of course everything's changed. We can't travel as easily as we could, gatherings tougher, all these sorts of things. But what hasn't changed is a brand's desire to be affiliated with a certain property or a brand's desire to connect with a property's audience. So those things haven't changed how we as an event property can provide those opportunities. That's changed. So that, and so that's on us to figure out, and I think now it takes more communication, more openness, less cookie cutter type partnership proposals and the ultimate flexibility to be able to deliver for partners. And it takes truly, truly listening to what is a brand's goal? What are they trying to achieve? Like I said, what keeps them up at night? (42:13): Mark Harrison always jokes that your job as a property is to get the person on the other side of the table promoted. So how are you going to get Joe Smith at X brand promoted up the food chain or to his next job? And if you can do those things, you are solving their problems. And I think we're living this right now. It's uncertain here in New Zealand. I mean, they had their first COVID case in whatever it was like 12 months back in August. And that toothpaste isn't going back in the tube here in New Zealand. They're trying to vaccinate as quickly as they possibly can to get to a place a lot of other places in the world are. But we're two weeks out and we're uncertain as to how many people will be on site. A lot of brands are actually based in Auckland and they're not on to leave because there's a border around Auckland because they've been able to, knock on wood, contain COVID within Auckland. (43:22): So the rest of the country's under level two warnings, but things are relatively normal. And so we've had to work with brands that are based here in Auckland that are sponsors of Crank Horse rota and try and create, we're working with one just this week about how can we create money, can't buy experiences for them, but they're in digital. And so we truly listened to what it was they were looking for, and we're in the process of creating and developing digital experiences for them that will allow them to continue to achieve their goals and what they were hoping to out of Kraner rot wheel, but in a completely different way.", "token_estimate": 612, "speakers": ["Darren Kinnaird"], "start_timestamp": "40:54", "end_timestamp": "40:54", "podcast_index": 80, "episode_name": "Ep 80: Darren Kinnaird | Event Marketing, Maintaining Sponsorships and COVID | Crankworx", "slug": "ep-80-darren-kinnaird-event-marketing-maintaining-sponsorships-and-covid-crankworx", "web_url": "https://www.portsidepro.com/podcast-feed/ep-80-darren-kinnaird-event-marketing-maintaining-sponsorships-and-covid-crankworx", "guest_name": "Darren Kinnaird", "guest_title": "Crankworx", "categories": [], "short_description": "Of all the industries to get hammered the most during COVID, the events industry has been hit hard. Forced to cancel, post-pone, shutter doors, and limit capacities. Events around the world have been struggling to operate with the restrictions.", "podcast_length": "52:50"}, {"id": "09c7d1b9-f649-44f2-ac31-0b0090acdb24", "episode_id": "8d72a24e-5891-43be-b320-ead7f102ad1d", "cms_item_id": "68225dfc7bb476527f8c4878", "chunk_index": 16, "content": "Cole Heilborn (44:10): So when big groups can gather again, how will the things that you guys are learning now translate to the conventional format?\n\nDarren Kinnaird (44:21): I think we will just have a whole bunch of new arrows in our quiver. I think mean, again, I cannot express how fortunate and lucky our whole team feels to have been able to push through the last 19 or whatever months it is now. But it has truly taught us a lot. We've got all sorts of new benefits and opportunities and things that we can provide for partners, and it's actually brought our team closer together, more cohesive. We, there's so much more emphasis on planning and planning to execute has been the focus. And so I think a lot of that will carry forward into the future, no question. We'll be able to, things are looking really positive in, I have my finger on the pulse mostly obviously in bc, but they just announced yesterday, October 20th as we're recording this, that as of October 26th capacities at indoor venues, there's going to a hundred percent for, they have a vaccine passport in bc. (45:58): And so if you're fully vaccinated, you're going to be able to go to the Connects game a hundred percent, which is really exciting. And so for us looking to next summer, knowing that our event is outdoors and there's so much of a lesser risk of transmission and who knows where we'll be anyways next summer, but we're really looking forward to being able to deliver Crankworx Whistler 2022, the full gamut. There might be a little few the things that are different, but we'll see. But we're really excited about the prospect of bringing everyone back to the mecca, as they say, of mountain biking. And so when we do, we're going to be able to bring back all of the old opportunities we had for partners, but have a whole new quiver of new opportunities as well.\n\nCole Heilborn (46:57): Great. If you had to, I don't know, give any message to fellow events directors or organizers out there who are still trying to figure out how to weather the storm, any thoughts, any advice?", "token_estimate": 517, "speakers": ["Cole Heilborn", "Darren Kinnaird"], "start_timestamp": "44:10", "end_timestamp": "46:57", "podcast_index": 80, "episode_name": "Ep 80: Darren Kinnaird | Event Marketing, Maintaining Sponsorships and COVID | Crankworx", "slug": "ep-80-darren-kinnaird-event-marketing-maintaining-sponsorships-and-covid-crankworx", "web_url": "https://www.portsidepro.com/podcast-feed/ep-80-darren-kinnaird-event-marketing-maintaining-sponsorships-and-covid-crankworx", "guest_name": "Darren Kinnaird", "guest_title": "Crankworx", "categories": [], "short_description": "Of all the industries to get hammered the most during COVID, the events industry has been hit hard. Forced to cancel, post-pone, shutter doors, and limit capacities. Events around the world have been struggling to operate with the restrictions.", "podcast_length": "52:50"}, {"id": "5a83c3ab-8892-49a3-aee0-4fc6cb63f950", "episode_id": "8d72a24e-5891-43be-b320-ead7f102ad1d", "cms_item_id": "68225dfc7bb476527f8c4878", "chunk_index": 17, "content": "Darren Kinnaird (47:11): Yeah, it's never too late to reach out to your community and you never know where those conversations are going to lead. When things did hit the fan last spring, that was one of the things that we started to do was just reach out to all sorts of people. What are you seeing? What are you learning? What are you doing? And I think that helped inspire us to come up with the ideas that we did. And I, I spoke to, I mean, spent weeks just on the phone talking to people, what are you thinking? What are you doing? How are you guys going to react to this? And that has led to some amazing new relationships, rekindling of relationships that people that we used to work with and all sorts of new opportunities for not just Crank works, but for us as a business. And so we're talking to people in France, people in the us, people in Quebec, people in Calgary, people in Australia about what are the future opportunities for Crankworx? And so for us, not only did it help us work with other entities to find common ground to keep things going, but also now it's led to all sorts of new conversations and new opportunities. (48:50): This whole idea of summer series, when we came up with it here in New Zealand, they're like, that looks amazing. Can we do one too? And so they pitched it to basically the south island, and we'll be doing the first ever Crankworx summer series New Zealand at the end of November for three weeks, end of the early December, and we're going to go to Alexandra in Otago, Queenstown, aka, and what's the place? I forget. But we're going to be going in and around Queenstown to share the stoke of Crank Works. All the athletes that have traveled here to be a part of Crank Works rota, a lot of them are going to stick around and race and be a part of this summer series. And so that's just one neat example of the things that have come out of this idea of reach out to your community, build connections, what are other people doing? And those that reaching out to the community did lead government entities to help provide direction and where are the opportunities for government funding to help get through all of this? And so we now have a direct pipeline to our NP in Cedar of Scott, and turns out he's a huge Crank Works fan, had been to the last 10, so you never know.", "token_estimate": 580, "speakers": ["Darren Kinnaird"], "start_timestamp": "47:11", "end_timestamp": "47:11", "podcast_index": 80, "episode_name": "Ep 80: Darren Kinnaird | Event Marketing, Maintaining Sponsorships and COVID | Crankworx", "slug": "ep-80-darren-kinnaird-event-marketing-maintaining-sponsorships-and-covid-crankworx", "web_url": "https://www.portsidepro.com/podcast-feed/ep-80-darren-kinnaird-event-marketing-maintaining-sponsorships-and-covid-crankworx", "guest_name": "Darren Kinnaird", "guest_title": "Crankworx", "categories": [], "short_description": "Of all the industries to get hammered the most during COVID, the events industry has been hit hard. Forced to cancel, post-pone, shutter doors, and limit capacities. Events around the world have been struggling to operate with the restrictions.", "podcast_length": "52:50"}, {"id": "73d87382-1d89-47b7-992c-b12da7e07046", "episode_id": "8d72a24e-5891-43be-b320-ead7f102ad1d", "cms_item_id": "68225dfc7bb476527f8c4878", "chunk_index": 18, "content": "Cole Heilborn (50:24): Wow, man. Well, anything, I think this conversation is one educational, it's a little inspiring just to hear that you guys are still kicking, still connecting the dots and providing opportunities for fans and for your team and for sponsors and athletes. We're kind of reaching the end of our time for today, but do you have any other thoughts, anything that we didn't cover that you feel like we should get out there?\n\nDarren Kinnaird (50:49): No. I mean, I think if I can lead people with things, it's reach out to that community, talk to your partners, constant communication and keeping them apprised as to all the scenarios and the challenges challenging you are facing as a property, because sometimes they want to help you solve them too. And because people are investing in what you're doing because they want to be a part of what you're doing, and that also means they want to help you continue doing what you're doing. And so those conversations have been invaluable. But yeah, I mean, I think, like I said, nothing's changed and everything's changed, and it's important to remember that that's just how we do things is what's changed, but what matters and what matters to everyone that hasn't changed.\n\nCole Heilborn (51:48): Well said. Darren, if folks want to follow along with you personally on the socials or with Crank Works, where can people go to connect?\n\nDarren Kinnaird (51:56): Yeah, so most of my handles are DW Cannard on Instagram and Twitter, and then at Crankworx on Instagram, Twitter, Facebook, all that, TikTok, all the things. Yeah.\n\nCole Heilborn (52:13): Awesome. Sounds good. Well, I'll let you get back to your exciting day of quarantine, and hopefully you can get out on more than one walk.\n\nDarren Kinnaird (52:20): I got another one planned for this evening, so I'm looking forward to it.\n\nCole Heilborn (52:23): Beautiful. Well thank you and looking forward to rot.\n\nDarren Kinnaird (52:26): Thanks, Cole. Thanks for having me on the show.\n\nCole Heilborn (52:27): Take care.\n\nDarren Kinnaird (52:28): Cheers. Bye-bye.\n\nCole Heilborn (52:31): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learn something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 578, "speakers": ["Cole Heilborn", "Darren Kinnaird"], "start_timestamp": "50:24", "end_timestamp": "52:31", "podcast_index": 80, "episode_name": "Ep 80: Darren Kinnaird | Event Marketing, Maintaining Sponsorships and COVID | Crankworx", "slug": "ep-80-darren-kinnaird-event-marketing-maintaining-sponsorships-and-covid-crankworx", "web_url": "https://www.portsidepro.com/podcast-feed/ep-80-darren-kinnaird-event-marketing-maintaining-sponsorships-and-covid-crankworx", "guest_name": "Darren Kinnaird", "guest_title": "Crankworx", "categories": [], "short_description": "Of all the industries to get hammered the most during COVID, the events industry has been hit hard. Forced to cancel, post-pone, shutter doors, and limit capacities. Events around the world have been struggling to operate with the restrictions.", "podcast_length": "52:50"}, {"id": "3d768359-8e87-40a0-916f-fa1c9faa2564", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 0, "content": "Jonathan Ronzio (00:00:03): There still has to be a respect for creativity, or you will have nothing but conflict in your career because marketing is finding creative ways to connect with your customer, to have a conversation, to build a community, to share your value prop, your brand story, to reflect your customer's pain points and be their guide because the customer is the hero, right? And so if you don't have a healthy admiration for creativity, you're probably in the wrong field.\n\nCole Heilborn (00:00:32): Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Port Sided Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Heur. Today I'm sitting down with Jonathan Rono. He's the CEMO of Cranial. He's an adventure filmmaker, and he's the host of the Stoke Cast. Jonathan, how are you doing?\n\nJonathan Ronzio (00:01:16): I'm doing excellent, Cole. Thanks for having me today. I'm excited.\n\nCole Heilborn (00:01:19): Yeah, likewise. Thanks for joining us. How's your week? Going?\n\nJonathan Ronzio (00:01:24): Week is going really good. I just got back to Massachusetts, so I'm based just south of Boston. I flew back in last night after a week, a whirlwind of a week out in Arizona where Tran is based. I flew out there for a 2022 leadership planning session that we took the whole team up to a mountain home and Flagstaff for that. That was pretty cool. We also had family out for a diabetes fundraising gala. My brother, our CEO has had type one since he was eight, and we did a whole fundraiser thing and the family was out. We got to a son's game. It was a blast. Really fun trip. And now I'm back and digging again.", "token_estimate": 537, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:00:03", "end_timestamp": "00:01:24", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "64cbd8ba-f8a9-4dae-bf57-2c8d334162ed", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 1, "content": "Cole Heilborn (00:02:05): Digging in and sounds like training for an Ironman too, huh?\n\nJonathan Ronzio (00:02:08): Yes. Yeah. Let's see. So training will sponsored an Ironman. It's in December, and so for the next three years, the Ironman 70.3 in Palm Springs in the La Quinta area is Theran Ironman. So it's like, this is not generally my wheelhouse, but I couldn't not do the race if our logo is going to be on the metal. So now, yes, in a month I have to do a half Ironman, and so this morning was a little mini try to see how I was doing.\n\nCole Heilborn (00:02:38): Gotcha. Right on. Well, when you're not training for half marathons or half marathons, you did one of those recently, but Ironmans, what do you find yourself doing? What are some of the hobbies you enjoy?\n\nJonathan Ronzio (00:02:49): I have a lot of hobbies. I mean, just before this show, before we kicked off here, I'm up in my music studio area, maybe you can't see because of the light, but I was just jamming. I had my guitar and was singing to a little bit of taking back Sunday, a little throwback for everybody out there who was into 2005 emo punk bands. I was jamming to a little TBS, so I love to play and write and record and sing and all of that rock climbing, mountaineering, ice climbing, ultra trail running, just adventure and adventure sports and all that stuff. I often think that the three areas of my world are marketing mountains and music and all things related to those things.\n\nCole Heilborn (00:03:40): Nice. The three M's.\n\nJonathan Ronzio (00:03:41): Yeah,\n\nCole Heilborn (00:03:42): I like that. Could you give us a little bit of a background on yourself? You do a lot of stuff. I feel like a couple of times I've chatted with you. You're always off chasing a new adventure or working on some new business project. Could you walk us through the history of projects that you've been a part of and what your role with CMO at Tral looks like today and what is Tral?", "token_estimate": 491, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:02:05", "end_timestamp": "00:03:42", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "5fda6ddb-8a55-4889-9a9a-759694dd5aea", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 2, "content": "Jonathan Ronzio (00:04:06): Yeah, yeah, I'll see how I can crunch this into something. I've always just had an insatiable kind of appetite for new experiences, just like a creative curiosity to create, to explore, to taste, and just push my limits a little bit. I was never the kid that liked to follow the rules. Maybe my parents didn't know that because I'd make them think I was following the rules, but then I'd really just do what I wanted to do. And I think that that curiosity and that dedication to autonomy first manifested itself in music. And so since I bought a guitar in sixth grade, started a punk band, that was the first creative expression that I really threw myself into. And I also feel like that was the foundation of where I learned the principles of marketing in terms of just poetic storytelling, writing lyrics and just the passion for creating something and then figuring out how to get people to hear it, how to get people to care about it, what's going to resonate, what is popular, what's not popular, do I care? (00:05:19): Do I not care if it is popular or not? Going through those motions at that time, and it was also the time that MySpace took off and peer volume and I'm learning how to take promo shots and build a website and work with the independent charts and start playing on stages and learn to express my voice in that capacity. And all of that happened alongside. At the same time, my brother had started a video production company. He's three and a half years older. He was in high school, I was in middle school, and I just wanted to also do what my brother was doing. So as I'm going through this evolution in music and just learning to be more creative and expressive, I also was learning how to audio production and recording. And then I learned some video stuff as I started working with him, and over the course of a decade, I helped him build this company, it's called Event Video Company, and we just recorded live amateur sporting events all around the country. (00:06:18): It started with the local, our hometown state cheerleading events and grew to dance competitions and ice skating. And we'd do some things randomly like car commercials, but mostly it was the live sporting events. And so I learned all of the elements of just audio and video production and how to hold a camera and what's good shot composition, and also how to manage events and manage people that were 15 years older than me when I show up and I'm like a 17-year-old kid who a year out of getting his driver's license and have to manage 30-year-old camera operators who were hiring for these events. It was a crash course in learning all different elements of business, but rooted in at least my side of it in the creative production realm. And we grew that nationally. And it wasn't until I was graduating school 2011 that smartphones were starting to become the thing they were in everybody's pocket and the parents who were buying all of the videos that we would produce at these events started just filming from the stands. (00:07:24): We saw the writing on the wall, and so ended up selling the business. I got out of school and I just moved to Aspen and I was like, all right, well, let's chase this. Let me think. How am I going to combine all of what I know about production and all of what I learned about marketing? I studied marketing at a business school, and again, I had those foundational principles and also everything I was passionate about in terms of adventure, which took root really when I studied abroad in New Zealand. And then I doubled down on when I got an internship with Old Spice where they sent me out to Switzerland to just snowboard around the Matterhorn and promote a new deodorant line, which was such a random thing that happened in the summer of 2010. But I just saw the intersection of where social media and production and brand storytelling and all these things were going. (00:08:17): And I was like, holy crap, I can do the adventure side, I can do the media side. And I felt like it was a perfect point of collision for me to capitalize on. And I put together an idea for a big adventure film project, and that was the reason for moving to Aspen, which I got to have a year as a bartender and snowboard instructor and just do the fun ski bum thing. But it was all for a purpose along the way of training for this broader goal. And then after a year, two buddies and I bought a one-way ticket to South America, and we had done the planning and put the processes in place to make this trip happen, which was called Between the Peaks. And we would go down and climb AUA and volunteer in every country along the way from South America to Central America until we got up to Alaska was the plan to then climb Denali. And so the plan was like, let's make an impact between climbing these two peaks and document the journey along the way. (00:09:16): That was my answer to how do I combine all these different things that I love? I was able to build the relationships with the outdoor companies. I remember my friend Ryan and I just sleeping in my car in Boulder Canyon climbing and then going and knocking on the door at Justin's nut butter and Backpackers Pantry and those businesses in the Boulder Business Park and handing out our flyers, telling them about what we were doing before we had any kind of credibility or clout. It was just trying to get people to bite on this idea. And once we got a couple to, it snowballed. And so that again was just this Next, I talk about the video company being this crash course, and then I feel like between The Peaks was this masterclass in my own entrepreneurial endeavor of learning how to put all the pieces together to actually make this giant thing happen, and to have the confidence to go for that huge of a dream that I had no business really going for, but making it happen. We only made it to Guatemala from Chile to Guatemala, and then we ran out of money and came back, but we had enough of a story to tell so broke at the time. I, for a year and a half edited this film while working at an ad agency in Boston, cutting my teeth in the content marketing world of experiential agency landscape. And then once I put the film out, it did pretty well and I quit that job and started my own media company, which was Explore Inspired. (00:10:51): And then for the course of five years, just pursued being an adventure content creator and stood on the back of Between the Peaks to build more relationships with outdoor companies and doing social content and brand campaigns and blogging and gear reviews and films and all sorts of stuff. And somehow it led its way to launching a systems and process like an ops SaaS tool with my brother there. Again, back in 2018, we linked up, and I'm sure we'll dig into this as far as what the catalyst was for the change, but I did take my foot off the gas of pursuing the Adventure Media career, at least for the time being to ride the Tidal Wave that was this tech company that we were on the brink of building. And I guess your last question was what is Train? Train is? It's a business playbook builder, so it's a software tool for small business teams to document processes, how they do what they do, their policies, just the playbook for what makes them them and help with their streamlining of scaling things, help people document and delegate what they do. And now we're almost four years into the business and we went from a few people at the start to now 82 employees and raised our series B round. (00:12:16): See that was a 27 million round we closed in June. It's been a wild ride.", "token_estimate": 1911, "speakers": ["Jonathan Ronzio"], "start_timestamp": "00:04:06", "end_timestamp": "00:04:06", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "14110658-2fcd-444f-93e3-de3ad9689640", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 3, "content": "Cole Heilborn (00:12:25): That's a lot. I feel like\n\nJonathan Ronzio (00:12:29): I told you I was going to struggle to make it, but I tried.\n\nCole Heilborn (00:12:35): Yeah, no kidding. Yeah. Interesting. I thinking I'm still just trying to grapple with the extreme differences between, but similarities also between all those different adventures. So what about filmmaking? What about storytelling and this pursuit of these intersections has always been of interest to you? Where did that passion come from?\n\nJonathan Ronzio (00:12:58): As a kid, I was always a quiet observer. I was never the class clown or the loudest. And this probably was because my brother was the loudest. He wasn't the clown, but he was very loud and very just front and center. He was the class president, he was the starting point guard. And so me as the second child, I was more the observer. I was in the background a lot. And so what that did for me was it made me very introspective. And so that probably lent itself initially to when I got into music, to just really having a passion for writing songs and trying to thread a poetic message and my feelings within that. And that catalyzed like, oh, this is my way of expressing myself. This is my strength, this is what I can lean into. And I knew that I was strong with analogies and metaphors, and I knew that I was, I've always been a lover of just pop culture movies from Disney movies to classic dramas and TV shows. And I try not to over index on consumption more than creation, but I am an avid consumer of just the popular media landscape. And then try to figure out how to reflect that in to what I can output. (00:14:13): It's hard for me to maybe pinpoint exactly what's the one thing that caused that, but probably once I picked up a guitar, I just really wanted to share stories. And then along the way, the guitar and the mic weren't the only way to do it, right? There was a camera and there was a computer and there was a phone. And now it's just exploring the different mediums in which we can tell stories, audio on a podcast. I've dabbled in all of it.\n\nCole Heilborn (00:14:48): Sure. And so where in that journey was the Stoke Cast? A part of that", "token_estimate": 550, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:12:25", "end_timestamp": "00:14:48", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "75b790da-4135-41c0-94be-df890537a733", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 4, "content": "Jonathan Ronzio (00:14:54): Stoke Cast started around the same time as Train, but it was like an overlap period where I still was growing Explore Inspired. My co-host Emily Holland, she who now does Nature Untold, and I think she does some stuff with you as well.\n\nCole Heilborn (00:15:13): Yep, she's awesome.\n\nJonathan Ronzio (00:15:14): Emily is fantastic. So I had met Emily at a climbing gym in Boston and we became friends and she expressed an interest to get into outdoor writing. I had a blog, I had a platform, and so I just invited her to contribute to share her stories. And so she initially became a contributing writer for Explore Inspired, and then the more she leaned into it, the more hungry she got, the more excited I got because I hadn't really attempted to scale Explore inspired outside of me at the time, just solopreneur kind of thing. And I wasn't sure that I needed to, I didn't have these grand ambitions to build a huge team. It was more like this was providing me the lifestyle that I wanted and I was able to travel wherever and have all these crazy adventures and it was just cool. And I would get contractors or freelancers or whatever, but I had never thought about building a real team until Emily started leaning in. (00:16:13): And then I started flying her out to Denver with me to attend Outdoor Retailer, and we started building relationships with the PR companies and the brands. And it was the first time that we were at the OR show that we were sitting down for dinner and she was like, Hey, we should start a podcast. You don't have a podcast. We've got the blog and all the videos and everything that we're doing, but podcasts seem to be taking off. And so I was living in Arizona at the time, getting Train off the ground as a part-time thing. I honestly didn't expect to be full-time and long-term with Train. It was just like I was helping my brother launch this thing as a partner to get it off the ground, but was like, yeah, after the winter in Arizona, I'm going to head back to Boston and then probably just keep doing my thing. (00:17:03): And that's not how it long-term played out. But so I, after the winter, went back to Boston and Emily and I started working on what is this show? And came up with the Stoke cast, and it was just like this is our avenue together to go out and talk to all the outdoor entrepreneurs and the athletes and the adventurers and the people that we would love to just learn more about and connect with and learn from 'em. And what we found out very quickly was that the biggest names in the game who we had admired all along, were not hard to get ahold of, and we were able to get them onto the show, and it just started scaling. We started producing, we did 83 episodes in a row without missing a week. And all of that happened along the same time as Growing Train. (00:17:56): It happened at the same time I was speaking, I was linked up with this company called a IP group, and they were representing me like booking me, motivational speaking stuff and leadership facilitation with companies like Hewlett Packard and Fortune 100 executive teams that I, so it was crazy, a freaking crazy year and a half. And I had to hit pause on a lot because she'll be the first to tell you how burnt out I got. I was sick on every red eye. I was on the road for two weeks of every month between going to the train team every single week to doing speaking events, to editing the podcast episodes at 2:00 AM to get them out the next morning. It just got crazy. There was too much. And I had to take a very honest look at where is the most momentum in my life and where is the most passion? (00:18:47): And at the time, stoke Cast still held the Passion Torch, explore Inspired was kind of on the backseat since I had got back from a month in Alaska filming for a follow-up to Between the Peaks where we finally made it to Denali, we went and climbed, and I'm still sitting on that footage, but that one I hadn't put poured any attention into what's next after that for that business. And Train was just growing like crazy. And so that had the momentum. And so I just was like, all right, I can't keep speaking. I can't keep doing Explore Inspired, I need to hit pause on a couple of things. Let me just lean into growing this tech company and continue producing this show, which to this day has never been monetized. It's just been a passion thing on the side to connect with cool people and share cool stories that motivate me and hopefully help others,", "token_estimate": 1131, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:14:54", "end_timestamp": "00:15:14", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "f51609b2-b703-4725-a922-c85c299d814d", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 5, "content": "Cole Heilborn (00:19:43): Man. Well, it's definitely a podcast that I've enjoyed listening to, so I appreciate all the work that you guys did and are still doing to make that show As awesome as it is, I'm excited for the hopeful comeback or reboot or whatever the future of it is. I'm excited to see\n\nJonathan Ronzio (00:20:03): There will be something. Yes, actually I did a mini thing where I just reached out to our community of listeners and was like, Hey, a lot of people have been DMing me asking for advice on their business or adventures or things like that. Just book some time with me and let's do a live chat. And I released eight or nine episodes of just totally candid live calls with listeners. And so that was the last batch that went out. And of course, Emily left to do Nature Untold to lean into a different passion for storytelling that she had about the sober stories and the outdoor community, which is such a necessity, and she's been doing so well with that. And so what's next? At the end of every episode, we asked every guest, what does Stoke mean to you? And now we're in the process of putting out a pre-production on a book that rounds up every single one of those answers, and is the definition of Stoke as told by a hundred outdoor advocates.", "token_estimate": 319, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:19:43", "end_timestamp": "00:20:03", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "77847235-9789-4541-8ca5-6a645bce16fc", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 6, "content": "Cole Heilborn (00:21:01): Oh, cool. Oh man. Well, we'll have to circle back on that when that does come out because that sounds like it'd be a good follow up. So I'm curious, it's obvious you're super passionate about a lot of different things about creativity, storytelling. I mean, you've directed your own film, but you're also out there bringing the CMO of a SaaS software company, which are just two totally different worlds, I feel like. So when I think about marketing and I think about creativity, it doesn't seem to intersect very well or collaborate very well with the process operations side of businesses. And I know you just gave a brief introduction to what Tral does, and I've got to give a quick shout out to the book that you sent my way, the Business Playbook, I'm enjoying it, I'm a couple chapters in, but there seems to be this tension between creative and process. And I'm curious if we can dive a little deeper into that tension and that intersection and kind of talk about how do those two worlds coexist and how have you figured out ways for them to coexist? I think when they do work symbiotically, they can produce great results, but figuring out how they can operate in the same room together is sometimes a challenge. So I know I just gave you a super broad question. I don't even know if there was a question in there, but let's start there.", "token_estimate": 343, "speakers": ["Cole Heilborn"], "start_timestamp": "00:21:01", "end_timestamp": "00:21:01", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "71f4eb2a-640a-48b4-b9ee-04b9a92daa02", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 7, "content": "Jonathan Ronzio (00:22:25): So I have never intuitively been the process person, the organized operational person, the business playbook, which you just held up. My brother wrote that book, and that always was natural for him. And so me on the other side, I complimented him with my just impulsive wild kind of creativity. And so along the way, he, as the older one, got to be an expert at delegating to me and I had nobody to delegate to. I became an expert at priding myself at taking everything on and being able to get efficient and learn real quick and figure out how do I do it all. But that is not a sustainable way to really scale anything. And that's probably where I did hit a wall with Explore Inspired was I wasn't thinking about how to do anything beyond me until even though Emily came on board, that was more or less the first time, I had to start thinking like, alright, well how do I teach her how to publish blogs and WordPress? (00:23:30): Lemme document that process. And so from a creativity to process index, I guess what I had to learn is you can't operationalize the creative spark, the creative engine, the ideas, the intuition. That's not something that you can document, but you can document the systems that enable that spark to fly to have more freedom. And so that's what I learned a little bit along the way. Train was just a beta kind of prototype. When I went to Denali and I had to, for the first time document, I'm like, all right, I'm going to be totally off the grid for the next month. I'm going to be living on a glacier. I'm not going to be able to produce this client content. I'm not going to be able to keep this newsletter going or publish this and that. And I had to document those things in this early version of TRA and assign them to my wife and to some freelancers. (00:24:28): And that was my first aha to wow. It's not about replicating the creativity, it's about replicating the guardrails that enable the creativity. And so let's say in video production, it's like you hire somebody to come and produce videos for you, and do they know right away if they should be exporting in 16 by nine or two by one, where are these videos going to live? What frame rate should they be shooting in? What frame rate should they be editing in? There's just so much of the minutiae of actually the creative output that can be process driven and can be documented and can make things more efficient and give you less headaches when somebody does something wrong, is really what you have to figure out. That's why often process documentation is such a reactive thing because you don't even think about it until something goes wrong, until you hit a wall. And then you have to think, well, how could we have avoided that? Okay, I could have told you this and this and this and this and this. Alright, so that's where I had to start learning what needs to be documented around the things that I do so that I can delegate to others and how do I build the systems and processes around my creative output to help others do the same, but you can't replicate the experiences of your life that inform your ideas.", "token_estimate": 785, "speakers": ["Jonathan Ronzio"], "start_timestamp": "00:22:25", "end_timestamp": "00:22:25", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "f778c489-df34-4b7d-80ef-2ad4497d217c", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 8, "content": "Cole Heilborn (00:25:56): So let's start also by just defining process and what that means and how does that connect to what tral does today?\n\nJonathan Ronzio (00:26:05): Yeah, so process is, it's the way something happens, right? It's the step-by-step like workflow of getting something done. And we think about train and just generally our POV on processes. It's not a to-do list. It's not a task management system. It's not project management rather than to dos. It's how tos, right? So you're documenting your process should be about explaining how to do something so that somebody else can learn the way that it should be done and then they just go do it. And you don't have to micromanage. It's not like you do this recurring checklist every single time. No, we're not sitting in the pilot seat of a 7 47 doing a pre-flight checklist every single day where you have to make sure that you're doing, it's just like you go through it. Once you get up to speed, you learn how to do it, and you can go back and reference it if you get stuck. But that's more or less what we think process enables. It's just like write down how it's done or show how it's done so that others are enabled to replicate the work.\n\nCole Heilborn (00:27:12): And what's the benefit of developing a process for an entrepreneur, a business owner, or just a manager of any sorts", "token_estimate": 339, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:25:56", "end_timestamp": "00:27:12", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "d10a19f5-2153-450b-b798-c93159315c84", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 9, "content": "Jonathan Ronzio (00:27:23): That you can live on a glacier in Alaska for a month and stuff still happens? The benefit, I mean, in a selfish context is that it doesn't all have to fall on your shoulders. You're not the only one in the company or in running the business or even working in the business that knows how it's done. Another benefit is that, let's say if you're the owner, you have one employee who's been with you for a long time who always did this one thing, let's say that they move on, you try to backfill that role or you try to step back into that role and you might not necessarily know the ins and outs of how it was being done at that moment. And so it'll take you time to get back up to speed. It'll take you time to get somebody else up to speed. (00:28:03): So it's a matter of efficiency, making sure that the knowledge of how your business works stays with your business From an employee standpoint, it's also an aspirational thing. I think a lot of people are fearful of codifying how they do what they do because they're fearful of being replaced. But flipping the narrative on that, it's like you will never move out of the role that you're in unless you can enable somebody else to step into it. So it's actually a really aspirational thing to take control of your career to figure out, let me get hyper-focused on what I do, let me get so good at it and let me start to write down the steps for how it gets done. And now I can train somebody else to do that so that I can take the next step and work on the next bigger thing, the next priority, because this is now a well-oiled machine.\n\nCole Heilborn (00:28:56): Sure. So I'm curious, when is the right time for a process to be built and shared? And I'm thinking specifically about in the outdoor industry, there's a lot of solopreneurs, whether they're creating products, services, at what point in their journey do folks often find themselves asking these questions and trying to figure out how do things work without me being involved at every step along the way?", "token_estimate": 512, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:27:23", "end_timestamp": "00:28:56", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "23692f8f-c35b-4ad3-9c39-b151565c6042", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 10, "content": "Jonathan Ronzio (00:29:25): The easiest way is when you notice that somebody's asking you the same question and five times in a row or multiple people are coming to you for the same thing, just recognize that that needs to be written down and shared. And I mean, another way is you can start to audit the things that you do that demand your time and attention, right? On a two week or a monthly basis. You can take a look at what was everything on my calendar the last two weeks? What was everything? Don't look in your inbox, look in your sent mail, then your inbox is going to be a bunch of bs, but your sent mail is the stuff that you actually responded to that demanded that you weigh in on something. So take catalog, what were those conversations? Who were they to? What was it about? And start to figure out what is everything that you are doing? (00:30:15): And then once you have that audit, you can start to think about where can I find a little bit more efficiency? Or even just a very honest conversation of what do I like doing and what do I not like doing? And once you have that, you've started to understand, these are all of my responsibilities. Bam, bam, bam, bam, bam. I've looked back at the last month, I've looked at all my messages, I've looked at my calendar, all my to-dos. These are all my responsibilities, this is what falls within my role. This is what falls just kind of outside of my role. How do I rearrange this into either a singular role that makes sense or into stuff that I like to do? And what can I, or should I pass on to somebody else? And is that somebody else on my current team? Or can I see a trend, a pattern here that's going to necessitate how I think about the next hire in my business?\n\nCole Heilborn (00:31:07): Gotcha. Interesting. Is it just a way to scale and control that scale and the operations that are happening within? Is that essentially the idea?\n\nJonathan Ronzio (00:31:16): It's a way to organize chaos so that you don't just go off the rails so that you can be more proactive than reactive so that you do take control over the important, not the urgent.", "token_estimate": 530, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:29:25", "end_timestamp": "00:31:16", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "f1cc30dc-ac6c-4a6b-9756-4cb06eefb54c", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 11, "content": "Cole Heilborn (00:31:31): Gotcha. So in your role with Tral currently as the CMO, I'm curious, you mentioned that operations and process in your mind kind of operate as guardrails and they don't restrict that creativity, but rather they support it and they structure it. How do you do that? I feel like you could cross that line very easily by having too many checklists or processes.\n\nJonathan Ronzio (00:32:01): Yeah. Well, I'll give you specific examples within our marketing team. So that's grown from just me doing everything in marketing to now a team of 13. And we've got a couple copywriters, video producers, social media growth, marketing, paid on and on and on and on the product marketing, there's functions and roles for now, almost everything within our team. That's something I've been really passionate about is building basically an internal agency model rather than outsourcing our marketing capacity. And so the stuff that I have documented for the team is I've learned to scale beyond me and my knowledge has been context. It's the gaps that people need to fill to do their work better. And that's somebody coming in, let's say I'm handing off running all of our paid ads, our Facebook ads or Instagram and Google and all of that. So if I'm handing off paid ads, somebody has to know, alright, where do we run ads? Where have we run ads? What has worked? What didn't work? (00:33:15): How do we respond to comments? What are the rules for hiding or deleting vulgar comments? So it's the context and the frameworks around how to operate that gives somebody what they need to know to excel. And then it's up to them to bring their expertise as well. To add on top of that, you always want to hire somebody who's better at doing that thing than you were doing it otherwise you might not pass it off. But once you bring somebody in, they have to know the baseline of where it's been so that they know what to try to accelerate it into the next level. And so that's kind of how I treat the marketing process documentation is it's not necessarily, again, trying to codify creativity or trying to exactly say this is how we tell stories, but it's like this is our brand voice, these are our brand colors and guidelines, and these are the channels that we play in and this is our general philosophy to acquisition and how we meet, what KPIs does the marketing team care about, and how do you work with the rest of the team? Who does what, if you need a graphic, what's the process for getting a graphic for the ad? So it's that kind of stuff. It's the operational things that enable work to be done and the historical context that enable better work to be done.", "token_estimate": 669, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:31:31", "end_timestamp": "00:32:01", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "73dcfbaf-6777-40f9-879a-34693e654dc8", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 12, "content": "Cole Heilborn (00:34:38): And are those things that you're organizing and putting together or is that a team process of organizing all of that?\n\nJonathan Ronzio (00:34:45): It's a team process for sure. I mean, it started with just me, but as the team grew, it's been a long time since I was managing the production of Theran podcasts and that has gone through a couple different people's hands. And so building a playbook is a team effort. And so now it's a shared responsibility. Everybody on the team can update a process when it's being done differently. So that actually just, we're going through this right now where we had been working with a freelancer who was editing some of the content and the audio for the podcast over the last year, and we just hired him on full time. And so the other parts of his role where he wasn't touching were transcribing the show, documenting the show notes, getting it published through Anchor to distribute onto the other platforms. And so now he's coming in taking those responsibilities off of our ops manager's plate. And so now we're having to update a process so that he can get up to speed and being able to do other parts of the work that he wasn't prior previously doing. But it very much is a team effort to make sure that the playbook stays up to date and that new hires and existing team members have the baseline need to knows to succeed in their roles.\n\nCole Heilborn (00:36:08): What does structured creativity, what does that, I dunno, what does that phrase mean to you or how would you respond to that?", "token_estimate": 390, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:34:38", "end_timestamp": "00:36:08", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "aced0a86-074e-4ad1-91f1-183442a97090", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 13, "content": "Jonathan Ronzio (00:36:18): To me, it's ruthless exclusion. I feel like structured creativity immediately. The thing that popped into my head was bowling with bumpers. When you go bowling and you get the bumper lanes. And so when I think about that, you can think about it from a negative standpoint and you can say that you're being limited and people might say that, oh, I'm being limited. My creativity has to be structured. It has to be within these bumpers. Or you can think about it as take control of the limitations. Start making them even narrower yourself. Give yourself, I forget who said it, but there's a famous thing that's like somebody wrote a massive three page letter and they were like, you could have, could you not have gotten this to me sooner? And they were like, well, it would've taken me 10 times longer to write a shorter letter. (00:37:15): It's harder to write short, concise copy than it is to write long wordy copy. That might not be the perfect metaphor, and I don't have the exact memory of what it is, but hopefully that point lands in terms of often the best thing that you can do when, let's say writing or even editing a film. And I've had to do this so many times where you're looking at a timeline of you've got 25 hours worth of footage and you need to tell a four minute story, and how do you do that? And you have to go through rounds and rounds and rounds of revisions to get it from 25 hours to 10 hours, to five to one to 30 minutes to 10 minutes to four minutes. And that is the process of ruthless exclusion. And ultimately it forces you to craft a better narrative.\n\nCole Heilborn (00:38:04): And I think you could look at all mediums of creativity or art and you could see similar process or structure that's required of each medium. I mean, I'm thinking about painting, you only have so much space on a piece of canvas to paint whatever you're going to paint.", "token_estimate": 478, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:36:18", "end_timestamp": "00:38:04", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "3608c0f0-bea3-4107-a199-18800a473c77", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 14, "content": "Jonathan Ronzio (00:38:25): Yeah, I mean, I think that you will always fill the size backpack you bring, right? Anybody listening to the show, I'm sure if they go out for a adventure and they're going camping, if they bring a 30 liter versus 75 liter, they'll probably fill whichever bag they're packing. That's just like when you have more space, you put more in. And so structure and limitation can often produce a better product and a better experience as much as US creatives might resist that.\n\nCole Heilborn (00:39:01): Yeah, but why is that? Why can those restrictions sometimes create better work?\n\nJonathan Ronzio (00:39:06): It forces you to think harder. If it's entirely limitless and there's no real directive, then you're throwing spaghetti at four walls instead of one wall and the spaghetti behind you might've stuck, but you didn't even realize it, right?\n\nCole Heilborn (00:39:33): I was thinking about the process of telling a good story before we were jumping on the show to record today. And I was thinking about of all the different ways, all the different stories that are out there, they all follow basically the same format. They follow the same process. And there's a few different processes that filmmakers choose from to organize their stories, but they generally boil down to five or seven of the most commonly used formats. And I thought, I don't know. I hadn't really thought about that before until I started to kind of mull over this idea today that all great films are built upon the same framework, the same structure, and they follow the exact same process. And so for something that says creatively liberating or artistically full of freedom, a film really doesn't have that much. You could argue because they follow the same three act structure or the Zach Schneider's Save the Cat or something about the cast. I can't remember what the structure is right now, but", "token_estimate": 476, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:38:25", "end_timestamp": "00:39:33", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "a2a266b5-e5cc-4c03-81be-4afddf1ff19a", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 15, "content": "Jonathan Ronzio (00:40:41): You tell a story to get relatability, you pose a problem, you offer the solution, you describe the benefits, you state the CTA and you get to the end, right? That's the general marketing storytelling framework, but translated to Pixar or anything else, right? It's like you establish the conflict or you show the backstory, you establish the conflict, you empathize with the hero, you meet the guide, you go on the journey. Yeah, you're right. I mean, it is very much the same. The recipe is the same, but it's the same way that you have three primary colors and can make any kind of work of art. You've got six strings on a guitar and you can play everything in the history of music nearly, right? You have finite ingredients with infinite potential.\n\nCole Heilborn (00:41:38): So recognizing that, I guess what is the opportunity or what's the connection? Why should marketers care about what we're talking about? Because I think there's a number of reasons that you could pull from it, but from an organization and a people management perspective, I guess, how would you respond?\n\nJonathan Ronzio (00:41:58): Why should marketers care about process and\n\nCole Heilborn (00:42:02): And creativity and why they really, it sounds like live in harmony together or they can.", "token_estimate": 325, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:40:41", "end_timestamp": "00:42:02", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "a66fc1f1-3e0b-4c62-b3ca-21d20d627259", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 16, "content": "Jonathan Ronzio (00:42:08): Creativity is the ultimate variable. I think if a marketer doesn't care about creativity, then they're not a marketer. I think even the more data-driven marketers, analysts and marketing engineers and all of that, there still has to be a respect for creativity or you will have nothing but conflict in your career because marketing is finding creative ways to connect with your customer, to have a conversation, to build a community, to share your value prop, your brand story, to reflect your customer's pain points and be their guide. The customer is the hero. And so if you don't have a healthy admiration for creativity, probably in the wrong field, where I can see people resisting a little more as I have done in my life is the process and the systems and the structure side. Because as a creative, you kind of just want to let your synopsis fire wherever they're going to fire. (00:43:20): But the practice and the process of having structure and systems, it's the pressure on the coal that produces diamonds. And that's what you have to really force yourself to learn and force yourself to respect is that if you want to take the next step in your career as an owner, as an operator, as an employee in any way, if you want to take that next step, you will have to learn systems and processes and structure and operations and communication. Unless you forever will just be a one man or a one woman solopreneur, a one person freelancer for hire who's just like, and that's okay too. If you're honest with yourself and you say, look, I just love to do character animation and that's all I ever want to do is just come to me and give me your concepts and I'll just animate. I love after effects, whatever that thing is. If you just love it and that's what you want to do, totally fine. But if you're trying to build a team, work with a team, grow a team, build a business, it's something you have to force yourself to respect and get good at.", "token_estimate": 494, "speakers": ["Jonathan Ronzio"], "start_timestamp": "00:42:08", "end_timestamp": "00:42:08", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "356bac61-b54a-49c7-8a4a-1621d2f07b71", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 17, "content": "Cole Heilborn (00:44:37): So for the individual who finds themselves in a marketing team that's growing, maybe they were like you not too long ago where they were doing it all themselves, and then they're slowly adding roles and expanding responsibilities, I guess what are some of the key tips that they should keep in mind as they're building these systems and trying to build the right amount of structure for their team?\n\nJonathan Ronzio (00:45:02): It's very dependent on the team size. I think if it's just you and your hire, you're making your first hire and a couple others, things are probably going to change and break so much that documenting too much or putting too many systems in place is just going to slow you down. And it's not necessarily worth the effort at the very early stages other than basic historical context, a log of what was done so that when you make your sixth hire, you have more context and they have more context and kind of fill in those gaps and have a better launching point. But establishing really, really strict standard operating procedures for your team and just a couple people, not probably the right move, but getting into just the culture of documenting along the way. And this goes back to just documentary filmmaking. I am just passionate about documenting the things that you do. (00:46:00): I think that it's, there's just something magical from the adventures to the struggles to the highs and lows and the ideas and the things attempted to what works and what doesn't work. It is just like make it easy for people to watch or read or listen and just learn from you along the way. And so I think establishing a culture of documentation from the start is smart, but getting too rigid on how strict you follow all the processes from the start is where you can be a little more pliable. But as you go start to have a broader team where individual members are really focusing on their lane, rather than doing a bit of everything in the early stages, everybody is wearing a whole bunch of different hats, and that's fine. But as you grow and you get to a team like we're at today with the marketing team with 13 or the broader team of 82, people have very hyper-focused roles now and need very specific instructions as they come in for the way something is done, and then they might change it along the way and kind of update that. Right?", "token_estimate": 596, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:44:37", "end_timestamp": "00:45:02", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "6bef91ca-12ef-450b-ac35-6402b0a1b8ff", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 18, "content": "Cole Heilborn (00:47:10): Yeah. Speaking of hats, I think you guys made an ad featuring all of the hats that business owners wear. Is that right?\n\nJonathan Ronzio (00:47:17): Yeah. Yeah. We've done a couple of them initially, so people might know the brand, they do a lot of drop shipping, and we always made for the Stoke cast, we did our swag through Printful, but I just found some trucker hats from Printful and just had labels one-off printed like CEO video marketing customer success, and just ordered a bunch of hats and then just stacked them on my brother and then filmed him going through the narrative of the steps he's taken in his career, all the hats that he wore. And in that video we launched last February, and it's crushed in terms of just Facebook ads alone. It's got 6 million views, and it's done insane for just trial and customer acquisition because it resonates. And it's not only entertaining the way we shot it, but it also tells a story that is helpful and that people can see themselves in and empathize with. (00:48:17): And that's kind of my perspective on everything we do with our marketing is to not just throw an ad into your face, but tell a story that our target customer can empathize with and can learn from, and then have the aha at the end. And then as part of our series B in June, we teamed up with Damon John from Shark Tank, and he was part of the Round, and so we were in Brooklyn, New York last June, and we shot a video with him where we stacked the hats again and did the whole Damon's story from starting and growing fubu. And all those years along the way, he was literally making the hats when he started the FUBU hats. And so we just thought it was a cool story to recreate, and that one's been doing great as well. So yeah, the many hats concept definitely resonates with people who feel overwhelmed and overworked and don't know how to take the next one off.", "token_estimate": 478, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:47:10", "end_timestamp": "00:47:17", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "68ce20ce-2bba-405c-9cf7-72ae10ca9805", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 19, "content": "Cole Heilborn (00:49:13): Sure. And I think that's what gets me excited about this type of a conversation is because hopefully some of these ideas can help people start to take off some of those hats and pass them off to people who are maybe a little more suited to wear the hat, maybe a little more excited, and that just allows the owner or the manager, the director, whomever, just to focus more on the thing that they're excited about.\n\nJonathan Ronzio (00:49:41): Ultimately, that's it, right? That's the end of the day. You don't join a business or start a business unless you're excited about what you're doing there. Hopefully, maybe a lot of, some people probably do take jobs, they need to take the job, but hopefully you're fortunate enough to be able to take a job with a company that you love doing something you love. And from a business owner standpoint, the whole reason that you take that risk to not work for somebody else, but to take that risk and work for yourself and start something, it's because you saw something was there, you had this passion, you had this knowledge, you had this skillset, you had this opportunity. It drove you to do something that you are passionate about and that you should love. And if you look at yourself honestly in the mirror at some point and say, I'm just burnt out by this and I'm not enjoying it anymore, that is a stark stopping point for you to take a hard look at what are the things that you are doing that are leading you to feel burnt out and unhappy, not necessarily the business. (00:50:49): You started it for a reason. So it's not the business, it's just what you have pigeonholed yourself into doing in the business. And so what steps can you take to get yourself out of that corner?\n\nCole Heilborn (00:51:04): Yeah. Did it take you a while to come to terms with the idea that just because their structure, your creativity doesn't have to be stifled or is that something that you readily adopted and understood pretty early on in your own career?", "token_estimate": 504, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "00:49:13", "end_timestamp": "00:51:04", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "37806cca-fa95-4380-a82a-f4dd68832e08", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 20, "content": "Jonathan Ronzio (00:51:20): No, I mean, it definitely took me a while to get there. I think that in my naivete starting the outdoor media production company, after producing between the peaks and then starting my own thing, I would go and pitch tons of brands on ideas that I thought were amazing, and I give them whole pitch decks and let's do this film and then this series and this, and I'd go to the table thinking this is exactly what we should do. And then it did take me a while to be able to swallow them coming back and be like, Nope, that's not right. Nope, I don't like that. And it's because they had different guardrails or different objectives from an outside perspective. I was looking and saying, this is what I think you should do. And they were coming back and saying, that won't move this business metric or that won't jive with this other campaign. And so that was my probably first experience of just learning. (00:52:24): The more preemptive communication and the more preemptive context you have to what those guardrails are, the better your pitch, your output will be. And then I get better at having the conversation beforehand rather than just going in and being like, this is going to be a game changer for your brand and we're going to do this super cool thing. It was like, no, we have a conversation. I understand what you're doing, what's on your roadmap, the things that have worked in the past, the message that resonates the strongest with this target audience and what your objectives are for next year. And now I have the information that I need to have a better idea. That's what changed the whole game from my understanding of how to fit creativity within the bumpers in the bowling alley was like, I'm not going to hit a strike with anybody unless I know what lane this needs to go in. I know what the objective is at the end of it. Right.\n\nCole Heilborn (00:53:24): Totally. Have you the book Creativity Inc, by Ed Kamal?\n\nJonathan Ronzio (00:53:28): I have not, no.", "token_estimate": 502, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:51:20", "end_timestamp": "00:53:28", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "84b5e7e3-4672-43aa-bf87-1333bd1e1e4d", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 21, "content": "Cole Heilborn (00:53:29): Okay. So he is, oh gosh, I can't remember what his title is, but he was one of the founding kind of principles of, excuse me, of Pixar, and the entire book is about culture and well process in how Pixar has created the creative culture that they have today. And it's really fascinating because he gives a whole bunch of specific tangible examples from Pixar's history of lessons that they've learned from. They also talk a lot about just kind of their philosophy behind their ideas, and it's amazing how much structure they have in trying to pursue these creative ideas and so much so that they design their buildings and their campus in a certain way so that it encourages collaboration and face-to-face time with the employees that hopefully those interactions in the hallways lead to some great creative idea on the screen. And so listening to him kind of talk about how much effort they put into almost managing the creativity or the parameters for creativity was really an eyeopener to me to understanding that no creativity, it's not just this rogue force that you have to just take control over you. You can prop it up and you can support it and figure out ways to kind of tap into it and almost force it to work for you, which I found really interesting.", "token_estimate": 322, "speakers": ["Cole Heilborn"], "start_timestamp": "00:53:29", "end_timestamp": "00:53:29", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "30d75bfe-37bf-45cc-9d84-f36365188e49", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 22, "content": "Jonathan Ronzio (00:55:07): Yeah, it's absolutely a sword you can sharpen. It's a skillset just like anything else that you can work on and craft, and it's, I hate hearing when somebody says, oh, I'm just not creative. You can work on it. It takes work. If you haven't felt like you're not creative your whole life, it's because you probably haven't created enough. The more you force yourself to create and taste and test and experience, the more I like to think of creativity as the space that exists in between unconnected ideas, right? Creativity is the ability to connect unconnected ideas, to draw some kind of bridge between things that shouldn't be bridged. And you can't do that unless you continue to experiment. But yeah, I mean, philosophy of everything at Pixar is a process. I love Pixar. It's everything they do is so inspiring. I don't know if you've seen the Making of Frozen two, but boom, that was incredible. It's on Disney plus. Anybody that, yeah, the making of Frozen will blow your mind in terms of the process that goes into producing those films. Unreal.\n\nCole Heilborn (00:56:30): As you look at the marketing landscape today in the outdoor industry, what gets you most excited? What stokes a fire?", "token_estimate": 307, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:55:07", "end_timestamp": "00:56:30", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "525f08ad-e985-4d16-8b04-190155a6f32a", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 23, "content": "Jonathan Ronzio (00:56:38): What marketing landscape in the outdoors? I think the outdoor industry, I think it contains the best storytellers in the world, honestly, the most authentic, the most passionate, the most real storytellers that are out there. That's where the grittiest stories are. That's where the most heart wrenching stories are. I love the outdoor industry and the people and the stories and the culture and everything about it so much. And I feel like my time and experience within it is what allowed me to succeed in the way that I have in a different industry in launching a tech company. I had no previous context or awareness of what was good or bad in HR and ops tech and what a normal SaaS marketing plan should be, and how brands were actually advertising in this space, how they were advertising on Facebook or Instagram or Google, and what worked or what. (00:57:50): I came in with a totally different perspective from the outdoor industry and applied that to this tech brand. And I think that's been part of the magic in terms of just telling a really human, authentic story from the start. That it's not just about advertising a software, it's been about talking about the people that are enabled by the software. And I learned that through the conversations and the stories told within the outdoor community. So I love the stuff that Duct Tape and Beer is doing. I love the stuff that Patagonia puts out, like the North Face, like Jimmy Chin is just on another level. It's just the talent that's cranking out of the outdoor media landscape is where I think more people should look to for modern marketing that connects with modern consumers.\n\nCole Heilborn (00:58:47): Do you feel like industries, yeah. Expand on that. Do you feel like industries could learn something from what the outdoor industry is doing?", "token_estimate": 460, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:56:38", "end_timestamp": "00:58:47", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "10dd34db-cf71-4aed-8d51-0c658a38afe0", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 24, "content": "Jonathan Ronzio (00:58:55): Absolutely. I think that even from a standpoint of just brands having a voice, and it is not just about the people and their stories, but these days, brands have a voice and have personality and look at what Ben and Jerry's is doing on their Instagram with the stances they're taking. And that's not necessarily new. Nike has been an activist brand for a long time, but it's more so than ever right now. And I think that the outdoor companies are generally on the front lines of not being afraid to take a stand, not being afraid to tell a story and to that might cause conflict and to fight for what they believe in. And I think the rest of the B2B and B2C landscape is in a huge shift right now, and I think there's a lot to learn from the bold stances, the bold ideas, and the bold stories within the outdoor industry.\n\nCole Heilborn (01:00:03): So we just talked about how great the industry is. I'm curious now if you could poke holes in it. What are some things that you wish the industry would do better or do differently when it comes to how it tells stories and how it just generally markets how it talks about marketing?", "token_estimate": 290, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "00:58:55", "end_timestamp": "01:00:03", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "edc63a42-cd23-44f9-b0c1-616f5e015dc1", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 25, "content": "Jonathan Ronzio (01:00:19): Well, conversely, to me, thinking that other industries should look to the outdoors, I think the outdoor industry has sometimes some blinders on. And I think that the outdoor industry is such a niche community and a siloed culture that I think the outdoor world is generally not looking to other industries enough as well. That's something that me having one foot in here and there and everywhere for so long, one of my struggles with the outdoor industry, as much as I love it. As much as I love all the people in it is that I sometimes felt like an outsider, even though so much of what I was doing was pouring my heart and soul into this podcast and this media publication and all the adventures and the mountains and everything that I was doing because I wasn't, this is probably a self-conscious thing, but it was sometimes because I wasn't living out of a van and because I was also at the same time like making websites for people in printing industry and because I was working on this tech company and I was doing all these different things and never felt like, I sometimes felt like there was a conflict of belonging.\n\nCole Heilborn (01:01:47): Oh, interesting. So continue with that train of thought. How does that connect to your hope or what you wish could be different?", "token_estimate": 328, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "01:00:19", "end_timestamp": "01:01:47", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "7918393a-f662-4bb2-bb8f-e6f9184d77f7", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 26, "content": "Jonathan Ronzio (01:01:57): Hard to say. I just think I am somebody who wants to live 10 lives in one life. Like you said at the start, I'm really passionate about a lot of different things. I love a lot of different industries and forms of creativity. And for me, it's not necessarily about the fact that I'm working on an outdoor podcast or I'm working on a tech brand, or maybe I'm launching a microbrew or maybe I'm backpacking South America or working on a competitive rocket to Elon Musk. For me, it's not necessarily about the thing. It's about am I having fun doing the thing? And that's what I think that sometimes you can chase your passion into a wall and you can think that you're doing the work that you love in the industry that you love, but by the very nature of turning your passion into that work, sometimes you fall out of love. (01:03:08): And so that's why I've tried to not hyperfocus on one specific thing and keep a lot of different lanes in my life because it's just like I've never been a sushi knife. I've always been a multi-tool and I don't want to be anything else. So I dunno. I guess that that's, I kind of talking in circles a little bit, but my hope is just that there was a Ted Talk, I forget who did it, but they called it Multipotentialite or something like that. People that just want to do tons of different things and have talent in tons of different areas can feel like they can still find a community and a place that they're accepted even when they're not 110% in that thing. And unfortunately, I think the current social landscape even perpetuates the problem where you can't build a TikTok following unless you do the same thing in every single video. (01:04:13): You can't build an Instagram following unless you are only posting your powder days or your workouts. When you start going off script, people don't know what to expect from you. And unfortunately, people like to binge. They like to binge watch. They want a regular episodic schedule of knowing what to expect and knowing that's you and that's your brand. And so I'm just hopeful that, not necessarily specific to the outdoor industry, but the broader media landscape, marketing landscape, industry landscape that we can widen the aperture on how we see people's lives and still respect that and that it can be aspirational to be good or even just not good, but to try a lot of things.", "token_estimate": 599, "speakers": ["Jonathan Ronzio"], "start_timestamp": "01:01:57", "end_timestamp": "01:01:57", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "89165719-a528-4a36-9d52-f0b62d5772cf", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 27, "content": "Cole Heilborn (01:05:07): Is that in part what gets you excited about the work that you and the team are working on at Train? This idea that the service that you provide ideally helps people from burning out and from wearing all the hats?\n\nJonathan Ronzio (01:05:22): Yeah, I love this is, I guess where I've landed is that I'm not focused on serving a specific industry either. We serve small businesses, entrepreneurs and small businesses. It's like if you've got five to upper end is like 500 employees, technically that's still a small business, mid-market a little bit, but five to 500 a little more narrow. It's kind of like 10 to two 50. But serving that market is incredible because yes, it does enable us to see a ton of different use cases. From a marketing standpoint, you might know Harmon Brothers, they're an agency that's responsible for the Poo commercials, the Squatty Potty, all those kind of super fun commercials. They use train to document their creative processes of how they do their production, how they bring their fantasy worlds to life in their commercials within outdoors. Like Protect our winners is Aran client. (01:06:26): They use Train to train their volunteers. After interviewing Mario Molina on the Stoke Cast, I dunno, last summer I just kind of stayed in touch with his executive admin and they ended up trying Triannual and I know their current clients, but I just love the diversity of stories that now get to be told that, that I get to learn and tell through these connections that are bridged through Triannual. And then also seeing the impact of what it has on people's lives, on teams, on businesses that are getting more structured, more streamlined, more standardized and more scalable. It's super cool,\n\nCole Heilborn (01:07:07): This idea of a bridge keeps coming up because I feel like in some way that's part of what makes you who you are. This bridging industries, bridging people together, connecting people, finding the space in between ideas and creating connections between them all. So I don't know, that metaphor just popped into my head as you were chatting there.", "token_estimate": 531, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "01:05:07", "end_timestamp": "01:07:07", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "f15c26b8-ca40-499f-9781-6b2445688b64", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 28, "content": "Jonathan Ronzio (01:07:29): I dig it. I'll take the bridge. We can stand on the bridge together.\n\nCole Heilborn (01:07:34): Cool. I like that. So I guess my last question, my wife would be really disappointed if I didn't ask about the ad that you guys put together featuring three cast members from the office. Can you explain a little bit more about what that was?\n\nJonathan Ronzio (01:07:49): Yeah, sure can. Alright, so for the office fans out there, and I'll ask you, you're an office fan?\n\nCole Heilborn (01:07:58): I am, yes.\n\nJonathan Ronzio (01:07:59): Who are the three cast members that probably would have needed the handbook the most? You did the employee handbook or a little bit of training more than anybody else.\n\nCole Heilborn (01:08:10): See, I feel like I've seen the ad a couple times now, so my answer might be a little biased. I would definitely say Meredith and Kevin, but I don't know, for some reason Kelly kind of pops to mind as the third cast member.", "token_estimate": 245, "speakers": ["Jonathan Ronzio", "Cole Heilborn"], "start_timestamp": "01:07:29", "end_timestamp": "01:08:10", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "d09b85ef-30f4-415c-85aa-52e8a93c84b3", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 29, "content": "Jonathan Ronzio (01:08:30): She was pretty inappropriate in the office. That's right. So no, we got, Stanley was our third, so we had Meredith, Kevin, and Stanley. So Leslie, David Baker who played Stanley Kate, gosh, why can't I think of her name right now? I'm blanking. Kate, who played Meredith and Brian Baumgartner, who played Kevin. So this was catalyzed by my brother and I went to TechCrunch Disrupt, which if you watch Silicon Valley, you probably would've seen the Silicon Valley guys go to TechCrunch Disrupt. It's just a big tech conference out in San Francisco every year. So we were there in October of 2019 and we saw Leslie David Baker just like the cartoon of his face on a sign just outside of the expo. And we had always joked that the office was just kind of a fun theme to play on. When we made our demos of Theran product, when we had email placeholders, it'd be like Dwight at Dun Mifflin. (01:09:41): So we just had that aha at the moment. We were like, what if we could reach out to Stanley or any of them and do an actual commercial with some of the people from the office? So first we went to see if we could get in touch with Stanley. We did. We were able to get into his email and connect with his business partner and then we were able to get a video from Stanley and there was no real production to it. Literally all we asked for we're like, Hey, what would it take for us to just send you some lines and you just film it on your phone and send it back to us? This doesn't have to be anything complicated. And so he did that and then through him we were able to connect. The pandemic hit just a couple months later before we even started running it. (01:10:25): And so we were like, well, it'd probably be better if we had a couple members because they had not been brought back together at any point for anything since the show had gone off the air. They were never in the same commercial or reunion or anything like that until mid pandemic. When John Krasinski launched the some good news show, he brought back some of them onto a Zoom for a reunion as there were so many Zoom reunions all over the place then. But Early Pandemic we connected with Brian and then Kate. And similarly we have videos from them just from lines that I wrote on a text and sent, and then they did the videos and sent them back super casual and then we displaced it together. And then we ran that ad starting in July of 2020 and ended up being nominated for some awards and absolutely crushed it for us on social with its virality comments, the shares, the engagement, the Clickthroughs. (01:11:28): It was incredible. And yeah, we just had fun with the fact that basically those three characters were just saying in the video like, oh, I never read the employee handbook, but I really should have. Things like that. Meredith is at the end of it holding up a bottle of Jamison as her character was just always drunk in the show and she's like, yeah, if you don't want employees like me, you need train. Something like that. So it was just a super fun, easy to create ad that we just got lucky we were able to, well, luck is part of it, but we had the intentionality to connect those dots and lucky that we got the response and we were able to pull it off.", "token_estimate": 817, "speakers": ["Jonathan Ronzio"], "start_timestamp": "01:08:30", "end_timestamp": "01:08:30", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "0f21b1b0-5f72-42ef-87ec-d74799ef99f3", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 30, "content": "Cole Heilborn (01:12:11): Yeah. Awesome. Well, we're coming up on the end of our time for today, but I guess any last thoughts that you want to sum up the conversation with?\n\nJonathan Ronzio (01:12:19): I mean, so much of today was just about I systems and processes and why you need structure in creativity or not. And so hopefully people took something away in terms of how to learn to delegate, why to document how to accomplish those big goals and keep their team aligned. And if anybody has any more questions for me, just hit me up. I'm at Jonathan. You can check out train train.com. You can look into all my past projects@justjonathanrono.com and yeah, that's kind of it.\n\nCole Heilborn (01:13:03): Perfect. Well yeah, I appreciate you taking the time to chat. I know it's not a super sexy topic, but I feel like it's a topic that I don't know, I don't hear a lot of people discussing, and I feel like there's definitely more conversations I feel like that could be had around this idea and kind of unpacking some of this stuff. But Jonathan, I want to thank you for taking the time to chat and share some of your experiences with us.\n\nJonathan Ronzio (01:13:28): Of course, Cole, thank you. Actually, was this valuable for you? I know you've been going down the process Rabbit Hole recently. You were reading E os, you got the Business Playbook, you were interested in this conversation. I'm curious where you're at.", "token_estimate": 357, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "01:12:11", "end_timestamp": "01:13:28", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "82908a8b-d9d7-4a90-8eec-89092e95ad4f", "episode_id": "3dc8b229-da8e-48e6-a5de-b0af3dd52552", "cms_item_id": "68225dfc7bb476527f8c4879", "chunk_index": 31, "content": "Cole Heilborn (01:13:44): Yeah, where am I at? I'm in the middle of documenting a bunch of our processes currently. So I'm knee deep in Word documents right now. Maybe I should look into cranial, but I think it is interesting and I think this conversation helped me kind of round or buff out some of the rough edges to some of my own personal convictions about creativity and structure and where they can live together. Yeah, I've always considered them to be two separate things, even though logically I have understood that they do coexist really well and they do need each other to be successful. But I think kind of talking out some of these ideas and listening to you share some of your ideas has helped me connect some more of the dots for myself. So I think I've got a few more things to think about and sleep on, but this is definitely helpful to me.\n\nJonathan Ronzio (01:14:39): You're on the bridge, you're connecting?\n\nCole Heilborn (01:14:43): I'm on the bridge. I'll let you know if I ever make it to the other side.\n\nJonathan Ronzio (01:14:46): Awesome. Well cool. This has been fun. Thank you.\n\nCole Heilborn (01:14:49): Yeah, thank you. I appreciate it. And best of luck with the Ironman.\n\nJonathan Ronzio (01:14:54): Thank you very much.\n\nCole Heilborn (01:14:55): Alright, we'll chat soon. See you.\n\nJonathan Ronzio (01:14:57): Alright, see you.\n\nCole Heilborn (01:15:00): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learn something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 400, "speakers": ["Cole Heilborn", "Jonathan Ronzio"], "start_timestamp": "01:13:44", "end_timestamp": "01:15:00", "podcast_index": 81, "episode_name": "Ep 81: Jonathan Ronzio | Why Process Leads to Better Creativity | Trainual", "slug": "ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "web_url": "https://www.portsidepro.com/podcast-feed/ep-81-jonathan-ronzio-why-process-leads-to-better-creativity-trainual-c292a", "guest_name": "Jonathan Ronzio", "guest_title": "CMO at Trainual", "categories": [], "short_description": "Jonathan Ronzio is the CMO at Trainual, a filmmaker, and host of the Stokecast. Any creative undertaking as an individual or a solopreneur can be daunting in itself. But as soon as you start to grow, you inevitably add more people to the mix. However, without a clear process, these people will create more work for each other and spend more time focusing on how to do the task rather than the task at hand. This issue is often felt in creative circles where the idea is that creativity and process don't mix.", "podcast_length": "44:103"}, {"id": "b3044a71-4fd2-4b36-afc3-c8c2e149adb9", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 0, "content": "Al Perkinson (00:03): And a lot of brands will look at an event as a place to sell their product, and so they calculate what's our return on investment. That is completely the wrong way to do it if you're a community-based organization. And so your attitude in that event should be bring the beer and pay the band. You want to make that a kick-ass party, so people who go to that event and other people who hear about the event, they're going to know who bought the beer and paid the band, and they're going to know who's just trying to be there to sell 'em some\n\nCole Heilborn (00:32): Stuff. Welcome to the Backcountry Marketing podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. I'm sitting back down with Al Perkinson. He is the founder and CEO of Bajo sunglasses. Al, how are you\n\nAl Perkinson (01:16): Doing? Great, Cole. How you doing, man?\n\nCole Heilborn (01:18): Fantastic. It's great to have you back on the show. We're coming back to finish up our two-part series that we started in episode 77, so thanks for taking the time.\n\nAl Perkinson (01:30): Great to be here, man. 77, that's a big accomplishment. That's a lot of episodes.\n\nCole Heilborn (01:36): I know. And I think this episode that we're recording today is going to be 82, so it's flying by.\n\nAl Perkinson (01:44): That's great. I didn't know there were that many marketing topics to talk about.", "token_estimate": 475, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "00:03", "end_timestamp": "01:44", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "d1ecc5ce-36d8-4147-95e5-f091a0112f11", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 1, "content": "Cole Heilborn (01:49): They keep popping up. I know. I assumed that maybe we'd hit 25 and we'd be done, but we're still going. So in the first part of this series, we had a great conversation about your five steps to building an authentic brand and what that looks like. And as we've been chatting since that call or before that call rather, you also have another five steps to building community in branding. And so at first we talked about doing those in the same episode, but then we talked a little more and it sounded like they're both worthwhile to give them their own episodes. So if you haven't listened to part one, I highly recommend jumping back a couple episodes to number 77 where Al discusses the five steps to building an authentic brand. If you've listened to that, I welcome you to part two. We're going to talk all about building community and what a buzzword for today, this idea of community. So I'm looking forward to jumping in.\n\nAl Perkinson (02:50): Yeah, me too, man. Happy to talk about all aspects of it. Community is kind of a buzzword these days, but it's hard to find another word that sort of describes what we're talking about. So I think it gets used a lot, but it's appropriate for what we're trying to do.\n\nCole Heilborn (03:13): So let's start by defining community. When we say we're seeing this in the industry, what does that mean? What are we seeing?", "token_estimate": 348, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "01:49", "end_timestamp": "03:13", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "138e9d13-32dd-47ce-b828-ed62d12ffa70", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 2, "content": "Al Perkinson (03:22): I don't know. I mean the way that I think about community might be different than how other folks feel about it, but I think a community, community is a basic human need. We're sort of pack animals and we want to be around other people like us, but the world is too big. There's too many people just be around the whole world. So you're around a subset of that world and those are people that you feel comfortable with you share values with. It used to be a long time ago that those were people who are your neighbors. Now a lot of us don't really even know our neighbors anymore. Some do and some don't. That's not really where the main place where we're getting our need for community from. Some folks got it from organized religion, and I think there's still some people who their church is sort of the center of their community, but if you look at the stats, I mean that's kind of declining in popularity. (04:36): So this desire to feel connected to other people and to find people who are sort of like-minded and believe what you believe, that's kind what community I think is all about. And one place that ironically, that people are finding community more and more is around shared passion, the things that they love to do, whether it's art or it's food or it's some kind of sport, that's something that is very important to people and it's something that they're building their community around. And brands play a really important part in that because brands are the tools that you use to explore your passion. And so they are by default, they tend to be an integral part of a community.\n\nCole Heilborn (05:34): You mentioned that brands are kind of in this natural position to help build community. What are some examples that you see or how have you been a part of community building exercises in the past? I know you've done some consulting for some brands and I'm sure this type of stuff has come up. Before in the past", "token_estimate": 489, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "03:22", "end_timestamp": "05:34", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "856553eb-0bc0-4635-889a-c889c626ca6f", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 3, "content": "Al Perkinson (05:54): I used to work for another fishing brand and we were engaged with all types of fishing. So we were engaged with bass fishing, offshore salt, inshore, saw fly fishing, I mean muskie, stripers, all these different types of fishing. And it was funny because when I would go to an event for one of those types of fishing, I found myself having to dress differently. So am I going to wear my bass fishing outfit to the bass fishing event and to the saltwater, to the offshore saw or fly fishing? And then I really started noticing that each of these communities kind of had different personalities and different values and they each did things differently. And so it occurred to me that these individual parts of fishing were sort of little subcultures within the fishing community. And that fishing as a whole was a bit of a subculture, but really for fishing there were sub subcultures. (07:06): And so I kind of got to the point where, look man, I'm sort of feeling schizophrenic here and I have multiple personalities and not only do I have to know how to do all these types of phishing, but I have to have a separate wardrobe for each one and not totally adopt a new set of values, but there's some red state and there's some blue state types of angling communities. And so from that experience, I sort of developed this, just sort of thought it through and wrote it down and started playing around with it and came up with this community-based marketing type of approach. But it started with just an understanding of looking at things like a cultural anthropologist might look at it and saying, Hey, this is a group of people that hang together and exhibit similar types of behaviors to each other and have different characteristics. (08:17): And so if you go in and you understand that hey, okay, this is a community and this community behaves this way, then you can develop a strategy for targeting that community. But it's really more about becoming a member of that community and joining that community, being a part of that community as a brand. So that's sort of how it evolved. And so we started putting that into place and I remember talking to one of the guys at ESPN and he was like, man, and my theory was, okay, I need to hire a community leader for each of these communities and then give them sort of the playbook on how to look at this community and then we can sort of own that community. I remember the guy at ES ESPN was like, look, dude, if you can do that, you will own fishing because you'll have more hands, feet on the ground, more intelligence about that community and your efforts towards that community will be dialed to a degree that nobody else is doing. (09:32): And so we did that and it was extremely successful. And so then I kind of shared it with some friends of mine who were marketers at other places like Yeti and other big brands like that. And so they implemented it and it worked. So felt like we kind of had this theory and we were all adding to it and improving it as we went along. And it was changing a little bit from company to company and community to community. But over time, it's probably been 10 or 15 years, it's really held up and it's almost like a secret formula for going in. Not secret for long, but for going in. And they used to call it niche marketing, but now we call it community-based marketing.", "token_estimate": 846, "speakers": ["Al Perkinson"], "start_timestamp": "05:54", "end_timestamp": "05:54", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "c34e09ac-d44c-4052-ac33-b98d4c03a4e9", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 4, "content": "Cole Heilborn (10:24): So you brought up a lot of great points there that I want to dive into and make sure we flush out thoroughly. So just to kind of clarify though, we're talking about this idea of community-based marketing and you mentioned Yeti, which is a brand that I think a lot of folks would look at as a brand that utilizes community-based marketing. How involved were you in their marketing journey and their startup process? Were you involved with that?\n\nAl Perkinson (10:51): Well, I was just as a friend, their first head of marketing, Rick, who's now over at Hower Brothers as head of marketing, there was a friend. And so we talked a lot about marketing. We actually go fishing in Montana once a year with some other marketers and we talk about stuff like this. And then Corey became the head of marketing after that. And so I shared this with Corey and he liked the idea, so I gave him the job descriptions for the community leaders and he went out and hired a bunch of 'em. And at that point they were growing so fast and so big that where I had two or three, I don't know how many he hired, he hired a ton. And so we just shared feedback and information with each other about things. And this was certainly a big topic for us.\n\nCole Heilborn (11:53): You mentioned that it's important for a brand to, there's a distinction between targeting a community and joining a community. What's the difference and why is that difference important to understand as a brand?", "token_estimate": 371, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "10:24", "end_timestamp": "11:53", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "01395a04-28d7-4eba-bcb9-db378c5bc522", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 5, "content": "Al Perkinson (12:06): I think this is one of the main reasons that I like to share sort of the secret of community-based marketing because I believe it's good for business and it's good for people. And so the more people that do this, I think the better off we are. And a lot of it is, I don't know if you look at AB boomers type of marketing marketing for the last 20 or 30 or 40 years, it's been almost militaristic and you're a company and you don't really respect the people you're marketing to. They are there to buy your product and for you to make money off of them. And so the consumer has kind of considered this almost anonymous type of entity or thing. And so lot of companies looked at the consumer as something to conquer. And so they developed these strategies and they developed target markets. (13:16): And so they would pummel communities with marketing messages until they couldn't take it anymore. And like, okay, I'll buy the freaking ring around the collar. I've heard it a million times, I will buy your product. It was almost an adversarial relationship. And with community marketing, I think it's not an adversarial, but it's more of a respectful type of relationship and it's one in which you want to become a part of this community. And one of the ways that you do it is by giving to that community. So you're not just taking targeting and trying to extract dollars, but you're actually trying to help build that community. And those communities are really important to people. If you're a cyclist or a mountain climber or a fly fisherman, your community is where you probably get the most joy out of your life is the time you spend in that community. (14:26): And so these communities, it's important that they stay healthy and it's no guarantee that they are going to stay healthy. And so the people participating in it, they want to come together and hold hands and say, how can we make this community better? And then the brands, if they take that attitude as well, which is more of a giving building type of attitude, then they're contributing to make that community better so they're contributing to people's happiness. And so I think having an attitude of you're not trying to take and target, but you're trying to join and build that everybody wins and that type of scenario.", "token_estimate": 578, "speakers": ["Al Perkinson"], "start_timestamp": "12:06", "end_timestamp": "12:06", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "e1eb1c07-fc6a-4d44-ba5d-67783d921eb2", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 6, "content": "Cole Heilborn (15:09): And when community-based marketing is being used effectively, I mean, what does it look like? What are some of the foundational elements that make a marketing initiative community-based marketing? How does that get played out?\n\nAl Perkinson (15:25): Well, I think it does start with that attitude of how you're approaching it. And so you're joining and you're giving before you even ask for a sale. And so it is kind of organic and it takes a little bit longer and it's not as easy to justify sometimes internally in a company because it does take a little bit longer and what you're building, you're building relationships and those relationships are hard to quantify. And it's not necessarily a media-based where I'm going to spend this much and I'm going to get this many impressions. It's much more of a relationship based, so I'm going to spend this much time and I'm going to win over this many hearts and minds. So that's something that if you're trying to justify what you're doing up the ladder, it's a little bit more esoteric and a little bit more difficult to do. (16:30): But what happens when you're successful is that the community rallies around you. And so having lived through the great recession like 2007 and eight, what we found was all the other brands, let's say you're talking to a retailer and at that time they're open to buy dollars shrunk because people weren't buying as much. Well, instead of taking that smaller pot and dividing it between three or four brands, they gave all that money to us because we were part of the community. We also found when we would sponsor a conservation group and for example, and other brands would say they were successful at sponsoring that group, well, our sponsorship wasn't based on just giving them money, but it was based on us locking arms and working on problems together. So they would actually turn down other brands who wanted to come in and become a sponsor of a conservation of their conservation group and they'd say, no, we've got our partner and that's good. So you see a lot more loyalty between all the members of the community and you see 'em actually trying to help each other out. So that's pretty unique in business to have that type of environment.", "token_estimate": 564, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "15:09", "end_timestamp": "15:25", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "e9064f38-7d56-43a0-a61c-3223b8b45acc", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 7, "content": "Cole Heilborn (18:02): Yeah, interesting. And I got to imagine if a brand positions themselves, it sounds like we could be using the word like friend, they're a friend in the community that's got to win over the loyalty and the hearts and the minds of the folks in the community.\n\nAl Perkinson (18:23): Like communities. One of the things you'd notice about a community is they like to get together and celebrate the fact that they are a community. And we call those events and a lot of brands will look at an event as a place to sell their product, and so they calculate what's our return on investment? We spent a hundred thousand dollars to sponsor this event that we sell a hundred thousand dollars worth of product, and that is completely the wrong way to do it. If you're a community-based organization, we say that ROI is DOA, right Debt on arrival. And so your attitude in that event should be, I would say bring the beer and pay the band because you want to make that a kick ass party. You want to make that event, you want to be part of that celebration and make it something special. (19:23): So people who go to that event and other people who hear about the event, they're going to know who bought the beer and paid the band, and they're going to know who's just trying to be there to sell 'em some stuff. You can see the people who work in the booth of that company that's just trying to sell stuff and they know they're going to get their ass beat when they get back to the office if they didn't get a good return on investment. And then you can see the people in the booth who are there to have a good time and to celebrate, and they'll probably sell more product than the other guys do, but the community's going to know what that brand did and that engenders them to that community and builds that brand loyalty and makes those deposits in that equity banks.\n\nCole Heilborn (20:13): Yeah, interesting. So let's dive into your five points. Can you summarize them for us and then we'll start back up with number one and dive deeper into what each of these points mean?", "token_estimate": 521, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "18:02", "end_timestamp": "20:13", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "8d01b5c6-f2b1-4092-8033-25e7e7c289a5", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 8, "content": "Al Perkinson (20:25): Yeah, so all communities have leaders, and so one of the tenets is, and these aren't really steps necessarily, they're just sort of components, but so all communities have leaders, people they look up to. So our mantra there is win over the leaders, not with your pocketbook, but with your heart and your soul. We want them to believe in what we believe in. Then number two would be adopt the cause. So communities have sort of a set of beliefs and values, sort of a religion. So you want to embrace that cause and further that cause for them. Then the gatherings we just talked about, goose, the gatherings, play the band, bring the beer, super important, join the conversation is we call that chatter. So communities connect themselves by talking to each other and communicating and there's a conversation going on. Join a conversation, don't interrupt it. (21:29): There's a whole school of thought on interruptive marketing. I kind of think that's bullshit. Nobody likes to be interrupted, it's rude. So join the conversation and be a part of it, make it more interesting. And then the last one sounds superficial, but it's looked the part. And that's why we hire community leaders because they come from the community. They're authentically a member of that community, and so they look and they feel, and they are part of that community. And so you're faced to that community needs to feel like that you're a member of that community. So the five things, leaders, causes, gatherings, conversation and look the part.\n\nCole Heilborn (22:16): Gotcha. So jumping back to point number one, this idea of winning the leaders. How are you guys at Behe winning the leaders? What does that look like?", "token_estimate": 430, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "20:25", "end_timestamp": "22:16", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "50d6d682-1ea1-44b2-b04d-0383731dd90d", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 9, "content": "Al Perkinson (22:28): Well, I have my community leaders who've actually been with me for a very long time and have luckily followed me over to Behe. They have relationships and they know that there's certain people that fit our brand and there's certain people that it doesn't mean they're a bad person or a good person, it's just are they a good fit? And so that's kind of the first question that we ask is who is likely to believe what we believe and to care about what we care about and sort of have the vibe that we have our bros, our team. And so then they identify those individuals, and some of them they might not know yet. They don't know everybody, so they'll do some networking, they'll talk to other people and certainly share what we're all about. And people are like, yeah, I know exactly where you're coming from. (23:29): You ought to meet this dude. And so it becomes this just networking and talking and conversation with these folks. And then when we do have the conversations, I mean literally it seems like it would just take forever and you're never going to be able to talk to enough people personally to make a difference. But there have been a lot of studies done that says a very small number of people can affect a very large number of people. And I think some brands have gotten it down to a hundred people can influence the entire community. Others have been nuts, like 10 people. And so just that network of influence. So finding who those influencers are, but also who are the ones that actually fit your brand. And then sitting down and having the conversations and trying to win them over just one person at a time before you even talk money and contracts and all this kind of stuff. It's like, Hey, would you be happy here? Would it be a good fit for you? Are you believing what we're believing kind of thing. And then when it comes to actually doing a formal agreement, it's super easy. You've already know that it's a great fit and it's not about money, it's just about a belief system. So that's kind of how we approach it.", "token_estimate": 515, "speakers": ["Al Perkinson"], "start_timestamp": "22:28", "end_timestamp": "22:28", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "dd2cbefd-f1d0-497b-9e2f-c93d47bf83f2", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 10, "content": "Cole Heilborn (24:56): When you say the leaders for you guys, are those your athletes, are those your ambassadors or is that how you're working with these community leaders?\n\nAl Perkinson (25:06): Yeah, leader to me is just, you could call 'em an influencer. It is just somebody that other people in the community look up to. And it could be, it doesn't even have to be the top dog. I mean it could be the president of another company in the community or it could be like some dude or gal who's in the marketing department or in the sales department, but for some reason everybody looks up to that person. It could be somebody in a conservation group, it could be a well-known scientist, it could be a writer, it could be an artist, it could be a professional athlete, but it's just people who influence other people and that others look up to.\n\nCole Heilborn (25:55): How do you work with these community leaders? You're talking about contracts. Are these employees, do they have their own lists of duties and responsibilities or are they just more of friends connections of people in the industry?\n\nAl Perkinson (26:09): Yeah, our community leader would be an employee of ours. They're the ones who coordinate all of the activities within that community, the leaders of the community, the influencers, those folks, there's a range. Some of 'em will want to do a formal contract and get paid money or get paid free product, be obligated to do appearances or to do social posts or stuff like that. Mean you can look at Michael Jordan was an influencer for Nike. He also had his own line of shoes and did all kinds of other things. So that's way up here. So it can be a whole range of agreements. Sometimes it's, there's no formal agreement at all. You flip 'em a pair of shades and they're like, yeah, man, I'm in and lemme know what I can do to help. So content is really big these days, and so being involved with content creation or just being part of your content is something that's pretty popular as a way to get involved.", "token_estimate": 507, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "24:56", "end_timestamp": "26:09", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "d26aef66-18da-476e-aa67-89086da35f0c", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 11, "content": "Cole Heilborn (27:29): Gotcha. So your second point adopting the cause or the belief system in the outdoor industry, is that, I mean, I think a common example of that is give back programs, conservation partnerships. What other ways or how does it go beyond something just like the 1% give back type deal?\n\nAl Perkinson (27:51): Yeah, it's really interesting. I guess there's two parts, a couple of parts to it. Maybe the conservation could be a value because if you're using this resource to really do the thing that you're passionate about, then you care about protecting that resource. And so one of the values of that community is protect the resource. If there's no fish, then we don't really have a sport anymore, so let's make sure the fish aren't going to die and let's make sure they're taken care of the same for mountain biking or any other type of activity. So that's definitely a core part, but there can be other things that are important to the survival of the community. Are we bringing new people in? Are we bringing young people in? Are we bringing women? Are we bringing various ethnic groups into the conversation and into the community? Because if the community is not growing, then it's dying, right? (28:56): You're either growing or you're dying. And so helping a shared value could be about winning over new people and within that being more inclusive, more open, less sort of cliquey or whatever. And so that can be part of a cause that you adopt within that community. There can also be stuff that's a little more, maybe less tangible and it could be an attitude, and so it could be about independence or freedom or self-sufficiency, those types of, if you look at Harley Davidson, what is that community built around? It's built around sticking it to the man. It's built around expressing yourself and being free and not being smothered by the constraints of society so that you can actually go out and explore and be free. And if you create films for example, talk about that, that celebrate that, then I would say that that's part of furthering the cause of that community as well.", "token_estimate": 528, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "27:29", "end_timestamp": "27:51", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "04c8fdab-1712-437f-94d9-406217045938", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 12, "content": "Cole Heilborn (30:18): Gotcha. So it doesn't just have to be a monetary or financial component. There's a lot of other parallels or things to consider as well when you join the belief system. So joining the belief system kind of sounds like you're signing up for a religion. Do you have to wholeheartedly believe with all of the commonly accepted beliefs within a community in order to fully join it?\n\nAl Perkinson (30:46): Yeah, it's a great question because it is sort of where religion meets commerce and you have to serve both masters in a way. So I don't know if it's necessary. I don't think it's necessary to hook, line and sinker adopt all aspects, but there needs to be something that you can embrace and that you can hold onto and that you can believe in. I mean, it just does because that's like the emotional tie that you have. And so many of these communities and so many of the things that hold us together as human beings are emotional, they're not rational, and the rational stuff's easy for everybody to do the emotional stuff super hard. I would say on some level, yes, it's important that you are part of that if you want this to be an authentic endeavor.\n\nCole Heilborn (31:57): Okay, yeah. Interesting. The third point, showing up at gatherings, being present, contributing. What does that look like?", "token_estimate": 331, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "30:18", "end_timestamp": "31:57", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "3f5cec7c-a072-446f-a571-b263e2b3d424", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 13, "content": "Al Perkinson (32:04): Well, sometimes it is literally bringing the beer and paying the band. Yeah, we did a college tour years ago and what we learned, and we just toured the country in an Airstream and threw parties for frat boys, and eventually there was a disconnect in the value system there. So we exited that eventually. But yeah, I mean the mantra there was cheap beer didn't have to be free, but it had to be cheap, great music and free shit is how, and if you had those three things, you would have a successful event and that's what the college guys were looking for. So you get the vibe of what makes this event cool and why do people come to it, and then you just try to pour gas on that fire, and that's what it's all about at the time was called the Teva Mountain Games. I think it's now called the GoPro Mountain Games out in Vail. (33:28): And for all the sponsors did a little summit and the guys who ran it, Joel Heath and some other guys, really smart guys brought in a guest speaker for all of us. And that was kind of the topic of his conversation that every one of you sponsors. If you're here to take something from this event, if you're here to argue about where your booth space is going to be and how big it is and just asking the people putting on the event to just give you more and more, then you're not going to be happy here and the event's not going to be successful. But think about what if everybody in this room said, how can I make this event better? Then we all benefit from that. And I just thought that was an incredible little speech that guy gave and it's very much in line with this whole community-based marketing approach. And so we've adopted that and I think it's a lot more fun to go about it that way and it is a win for everybody.\n\nCole Heilborn (34:42): It sounds like points three and four kind of blend together. You're showing up at the gatherings and then you're joining the conversation, but those are distinct points for a reason. Why is that?", "token_estimate": 500, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "32:04", "end_timestamp": "34:42", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "716bcefb-2868-4c93-97bb-5377e48632b2", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 14, "content": "Al Perkinson (34:55): Well, that would tend to be more around marketing communications in terms of joining the conversation, and certainly one type of communication is at an event where you're talking to people directly. But from a more theoretical standpoint, if you think about, let's say you're at a cocktail party and you walk up and there's a group of three or four people and they're talking about a, let's say they all love fishing, and so they're talking about fishing and they're talking about some trip that they've taken to South America or to wherever, and you walk up and you interrupt that conversation that they're having and you're like, sorry, I know y'all are talking about fishing, but let me tell you about myself. Here's where I went to school and here's where I work and here's my strengths and maybe I have a weakness, I haven't found it yet. (35:52): And then you say, what's going to happen? They're going to turn to you and be like, who is this jerk? And so they're not really going to want you to be part of their group. On the other hand, if you walk up and you kind of listen for a while and you understand, Hey, what are they talking about? What's the conversation about? And you're like, oh, well, I like to fish too, and I've been to that place that they're talking about. And then you say, with a little humility, I went there a couple years ago, I know what you're talking about. That was really cool. And then they're like, oh, really? Yeah, okay. Did you catch anything? Yeah, caught this fish. And then all of a sudden you're part of that little crew, you're joining a conversation instead of interrupting the conversation. And so it's just kind of an analogy for marketing communications. It's all about storytelling, and it's about telling stories that are of interest to the community and being part of that conversation", "token_estimate": 465, "speakers": ["Al Perkinson"], "start_timestamp": "34:55", "end_timestamp": "34:55", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "0b2e06da-156a-4007-bff5-9c7ab6cfa7d8", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 15, "content": "Cole Heilborn (36:58): In that story, it makes perfect sense. No one in that social setting would want to go grab a drink with the guy who just interrupted them. But why is it that interrupting interruption? Marketing tactics are a thing and tons of people use them, but socially that's a very odd practice. But when it comes to marketing, that's the thing that people use all the time. Why is that? That seems really obvious.\n\nAl Perkinson (37:27): Well, I think of brands as people, and it's really a company and a company is made up of people. And so marketing is really just you having a conversation with other people. So everything is very much to me in human terms. And you've had this expertise within business and marketing built up over the years to where it makes it not human, but it makes it, I don't know. I don't know what people think companies are, but it's almost like they're not made up of people and of humans, but they're this other thing. And people will say stuff like, oh, it's just business. Well, what do you mean? It's just business? Is me as a person having an exchange with you, a person, how is that any different than a social conversation? So I think they're one and the same. It's more of a humanistic, human-based type of approach to business and to communication. (38:42): And people are going to either be on receive or they're going to be on send or they're going to be on block. And so if you're trying to tell them about your product, what's the easiest way to get them to open up and be receptive to that conversation? I think it's in the way that we talked about as opposed to just, and the thing is, people, we used to not have control of the commercial messages that we were fed. There used to be three networks and you sat down and there were 32nd commercials and 62nd commercials, and you had to sit there and watch those commercials. You didn't have a choice. And so it was very much sort of a force feeding type of arrangement. Now the consumer has finally pretty much gotten control over what messages come to them and they can pick. And so it better be a message that they're receptive to or they're not going to let you in.", "token_estimate": 544, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "36:58", "end_timestamp": "37:27", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "bcaeda9d-b27c-4dda-ab18-b09fa9d74b4d", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 16, "content": "Cole Heilborn (39:50): So in your guys' marketing today, what's your messaging? How do you speak about your product? Are there certain tactics that you just won't touch or even recognize because of this pillar of joining the conversation rather than interrupting the conversation?\n\nAl Perkinson (40:12): I have to be pulled, kicking and screaming by my people, my staff, to talk more about our product. But I think if you talk about the product, you talk about it in terms of the benefit, and if we have a lens that blocks significantly more blue light, which reduces haze, makes everything clear, and it has a rose base so that it has high contrast. So the benefit of that is you can see more fish and you can catch more fish, and so you're going to have a great time on your trip, then that's a message that folks might be a little bit more receptive to than just talking about the features, talk more about the benefits. But then there's a heavy dose. We have a series now called Fishing with Jay, with Jay Johnson and Jay is in the old Bojo school bus traveling around the country talking to fishermen and fishing with fishermen and just having a great time. And that's something that we don't talk about the product at all. It's obvious because Bahi was written by a tattoo artist tattooed on the side of the bus, but it's not in your face. And really the star is J and the star is the story.\n\nCole Heilborn (41:39): But it sounds like you make a cognitive decision to talk personally to talk less about the product. Is that correct?", "token_estimate": 385, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "39:50", "end_timestamp": "41:39", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "43e4e593-a123-412d-b109-33f093176cc9", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 17, "content": "Al Perkinson (41:48): Yeah, if you make a product, I had a PR person one time and I said, I want to get some feature stories and some magazines, something that's like a real meaty kind of story. And she goes, okay, well what are you doing that's worth writing an article about? I said, well, how about our product? And she goes, no, man, everybody wants to talk about the product. They think their product's the best everybody does, so give me something interesting. Give me something that's real, that's something that's not product. So that kind of forced me to think about that. I'm like, wow, what are we doing as a company? What are we doing as a brand? What are we doing to improve the world? Help the world? What are we doing that's funny, that's crazy. I better go do some of that stuff. And so I think that's just kind of human nature, not to just listen to people talk about themselves and talk about their product, but to want to hear something that's cooler than that.\n\nCole Heilborn (42:55): When is it appropriate then to talk about the product or the service?\n\nAl Perkinson (42:59): Well, if you're into online marketing and you got the funnel, then top of the funnel is the really fun, interesting stuff that's going to get people to say, oh, I'd like to check that out. And then as you move down the funnel and you're like, okay, I'm considering buying this product and so I'm going to want to know certain things. I'm going to want to know about what is the base lens color, what is the light transmission? What are those specific things? Because that is going to impact my decision to buy it. It's going to impact how it performs doing the thing that I want it to do. So when you get sort of bottom of the funnel and get close to that purchase decision, people are going to demand that you give them that information.\n\nCole Heilborn (43:44): So your fifth point, look, the part you mentioned earlier that when you'd show up at different gatherings with different, you'd have to put down different types of clothes for the different events. Is that what you mean? Putting on the right wardrobe to fit into the right crowd?", "token_estimate": 535, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "41:48", "end_timestamp": "43:44", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "6a5bb343-d1fd-4d6c-8714-391062d73861", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 18, "content": "Al Perkinson (44:05): I think that's part of it. That's sort of the outer skin, but there's sort of an inner skin as well. So you've, there's an attitude, there's a philosophy that you need to adopt that becomes apparent when you talk. And so I think looking the part on the outside and the inside, on the outside though, it becomes a, for that community that helps you identify yourself and others identify you as a member of that community. And people are proud about that. You want somebody to stop you in the airport because wearing a certain type of shirt or wear of glasses or a hat like, oh, you like to trout fish? Yeah, I do too. Man, I can't tell you how many conversations like that I've had in airports and just out in public where you instantly make a friend because they see that you love the same thing that they love and they identified you by how you looked and whatnot. So I mean, I remember being out west and we got our Southern Prep boys who were out there working in a fly shop for the summer, and they're driving a certain type of vehicle, probably an old beat up four runner. They got the baseball cap on, they got their Patagonia shorts, and they've got their guy Harvey and their sunglasses hopefully. But at this point, but you're like, that's our guy right there, man. I can tell he looks the part.\n\nCole Heilborn (45:43): So how does a brand look the part, I mean obviously the employees could wear the right clothing, but the outside the image of the brand, how do you guys look the part?", "token_estimate": 380, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "44:05", "end_timestamp": "45:43", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "06eb2580-ea95-49d5-881d-e397dfbf8018", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 19, "content": "Al Perkinson (45:55): Well, sometimes it's difficult because they're different looks for different parts. Certainly all the printed materials that you do, all the advertising that you do, the people who represent your brand at an event, all of those are sort of outward facing, whether it's graphics or it's clothing or whatever that send a signal that you are kind of on the right page with that group. Where it becomes kind of difficult if you're in multiple communities is what does your website look like and what does your social media presence look like? Is it sort of a hodgepodge of all this different stuff or what is that connective tissue that everything has in common that you can put up there? Everybody can kind of relate to\n\nCole Heilborn (46:53): How do you balance multiple images in the fishing space? You've got the alpine trout fishermen, but then you've also got the deep sea halibut fishermen. If you're talking to both of them, how do you appeal to both of them without making yourself look like you're neither of them?", "token_estimate": 261, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "45:55", "end_timestamp": "46:53", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "38f96281-f635-4651-bc62-b357e345f264", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 20, "content": "Al Perkinson (47:14): Exactly. Well, one way is to say, look, what did they all have in common? Where's the common ground? And for us at Behe, we're a young brand and intentionally, and there hasn't been a new fishing, there hasn't been a new performance sunglass brand of any significance in the last 40 years. And so we are that next generation brand. That's part of our strategy, that's just part of our passion with youth. So let's make sure that everybody that we show is in their twenties or 18 to 25 or whatever, and it doesn't matter what kind of rod they have in their hand or what kind of fishing they're doing, but they look like our crew. And then let's make sure that the attitude that they're having towards the activity that they're doing, the vibe of the whole thing is inclusive, it's fun, it's adventurous. (48:15): All those values that these guys have in terms of how they approach the activity, make sure that that is consistent. And then that goes a long way towards bringing people together really and talking about, Hey, these are the things we all have in common. Let's not get so hung up on what kind of fish you're catching or what kind of rod or reel you're using. Let's talk about the bigger picture of why we do what we do and what is that common belief system and that common set of values. What's the thing that turns us all on about this? And the tug is the drug or whatever you want to say, but that's kind of corny. But there is something about the stalking of the fish, about understanding nature and how in order to catch the fish, you've got to understand how the bugs behave, how the water, whether it's tides or whatever or how the weather behaves, the high pressure, low pressure, you've got to understand so much. And in order to really embrace that means you have to love it. You have to care about nature. And so the idea, I mean, I have sat with a big old, burly, redneck ba dude and watch him wax poetic about the beauty of a sunset. That's not the stereotype of that dude, but that is what's underneath pulling that out and as the common ground can help pull all that stuff together and make it feel like it's coming from the same place.", "token_estimate": 546, "speakers": ["Al Perkinson"], "start_timestamp": "47:14", "end_timestamp": "47:14", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "3053a169-56fa-4274-83f2-daa86611e8d9", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 21, "content": "Cole Heilborn (50:03): Yeah, that makes sense. Well said. At the top of this conversation, you said that if you're looking at community-based marketing and trying to identify the ROI, you're doing it wrong, your perspective is already off, your why is already misaligned. How do you know then if what you're doing is working because the RO exists? Because we want to know what we're getting out of the investment. So if brands are investing in community-based marketing without the monetary component, how are you evaluating? Is this worthwhile? Should we keep pursuing these five points?\n\nAl Perkinson (50:45): Well, brand loyalty is certainly one of the things that you look at. And so you can measure brand loyalty. There are a lot of different ways to do it, but one of which is, Hey, would you recommend this brand to a friend basically? And it gives you a score, and that score is something that's sort of used across various industries and products and so forth. And so there's that kind of quantitative look at it. And then there's also a qualitative piece to loyalty. I remember asking my research company one time the same question. I said, is there a way to come up with a brand love index and I want to measure brand love? And they're like, Hmm, nobody ever asked us that before. But yeah, I think we can do it. And so each, I think it was every quarter we did a brand love study to see relative to other brands how much love there was for us in the same category compared to the others. But that's basically what it comes down to. Trust and loyalty and love are the things that you're trying to build. And it's kind of like profit is not the goal, it's the result. And so if you have people who are loyal and who love you, I bet your profit's going to be really good.\n\nCole Heilborn (52:24): I'm curious, how did you begin to measure the love factor? What went into that?", "token_estimate": 471, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "50:03", "end_timestamp": "52:24", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "2b146de2-ab96-4b67-bb29-3fcc8df2b45e", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 22, "content": "Al Perkinson (52:31): Well, a lot of it was just are you willing to recommend to a friend? And so there are questions like that, and I'm trying to remember what the actual questions were, but it is kind of common sense, and you ask people things like, if something happened and you could no longer buy this brand, what would that mean to you? And if you're like, oh, I just get another one that's not really, they're not loving you, they'd be like, I would be heartbroken. That could never happen. No other brand would live up, then they probably love you pretty good. So it was more in that ballpark of types of questions we would ask.\n\nCole Heilborn (53:24): Gotcha. This just made me think of an episode we recorded with iex, with Bonnie Shup and Jordan Totter Roth. So IEX recently relaunched in the last couple of years, and they were sharing just about how much disappointment there was when the original Ibex had to shut its doors and people went out and just bought as much remaining IEX clothing as they could because they weren't going to be able to get it anywhere else. Now that it's rebooted, Bonnie and her team are hearing stories of loyal customers coming out of the woodwork, ecstatic that they're relaunching, but also being like, Hey, I've got 20 pieces of your clothing in my wardrobe because I love you so much, and I was scared that I wouldn't be able to get this ever again.\n\nAl Perkinson (54:13): That's brand love for sure.\n\nCole Heilborn (54:15): Yeah, no kidding, man. So I'm curious, as you look towards the future, how are you trying to improve your community-based marketing? Are there points? What are things you're doing really well? What are things that could be improved upon?", "token_estimate": 428, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "52:31", "end_timestamp": "54:15", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "2e502a15-444d-46f6-be33-8f44737cd365", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 23, "content": "Al Perkinson (54:31): Well, one of the things I think can be improved on is including the retailers as part of the community and just recognizing, I mean, obviously they're part of the community, that's where people go to buy, but sometimes there's sort of this division between sales and marketing and they don't work closely together. But if you think of retailers as more like community centers and places that people go to meet and to connect and to gear up, then those retailers are an incredibly important part of that community. And so really having them be a bigger focus in community marketing is something that we're trying to do and improve on. I remember when we moved to Tallahassee, my son was a cyclist, and so all he did was go down to the bike shop and within 30 minutes he had met 10 people. He was on a team, he found his community right there, and he did it all through a retailer. So they're incredibly important. And so I think that's one key way that we want to improve.\n\nCole Heilborn (55:48): Gotcha. Right on. Well, we're coming up against the end of our time for today, but I've really enjoyed this conversation. It's been incredibly insightful, and now that you've kind of broken down these five steps for us, I can kind of start to look at brands and start to see how these five points are integrated into everything that they do. Again, I think I said it in the last part one, but it's only five steps. It should be easy, but it's not easy. These are very difficult, intentional, long play steps. So being able to see them broken out and identified, I think is really helpful.\n\nAl Perkinson (56:28): Well, good. I hope it's helpful to everybody, and like I said before, community taking this approach to business and to marketing, I think it's healthy. And so I hope more and more people will start using this approach. For sure.\n\nCole Heilborn (56:42): Yeah, right on. Well, where can folks again go to connect with you guys?\n\nAl Perkinson (56:49): Behe sunglasses.com, and then we're up on Instagram and Facebook as well. So I think you'll be able to see some of our communities in action at those places and hope everybody enjoys it.", "token_estimate": 542, "speakers": ["Al Perkinson", "Cole Heilborn"], "start_timestamp": "54:31", "end_timestamp": "56:49", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "fa7377f7-e3bc-4728-b19c-116ec88a3ae2", "episode_id": "8825f7c8-9bbc-4c4e-b8e8-5682690062ee", "cms_item_id": "68225dfc7bb476527f8c4877", "chunk_index": 24, "content": "Cole Heilborn (57:02): Awesome, Al. Well, thank you again for taking the time. Who knows, maybe we will come up with another part three and four as we keep chatting. I feel like the more we talk, the more I realize we could keep talking.\n\nAl Perkinson (57:15): Super fun call. Happy to do it anytime, man.\n\nCole Heilborn (57:18): Alright, thanks Al. Take care.\n\nAl Perkinson (57:19): Alright, see you.\n\nCole Heilborn (57:22): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 159, "speakers": ["Cole Heilborn", "Al Perkinson"], "start_timestamp": "57:02", "end_timestamp": "57:22", "podcast_index": 82, "episode_name": "Ep 82: Al Perkinson | 5 Steps to Building a Community | Bajio Sunglasses", "slug": "ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "web_url": "https://www.portsidepro.com/podcast-feed/ep-82-al-perkinson-5-steps-to-building-a-community-bajio-sunglasses", "guest_name": "Al Perkinson", "guest_title": "CEO of Bajio Sunglasses", "categories": [], "short_description": "Al Perkinson, the CEO of Bajio Sunglasses, joins me on the podcast for Part 2 of this series. We pick up the conversation where we left off in Part 1 of episode 77.Creating and building a community is all the rage. As marketers, we want to build companies that are surrounded by loving, supportive, passionate community members.", "podcast_length": "44:104"}, {"id": "fab76de8-c1c1-4e4c-9c0b-45f4c18214cd", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 0, "content": "Jeremy Jensen (00:00:03): It is when we feel the most alive. This is what makes life worth living. These are some of the most meaningful moments in our lives, whether you're on a snowboard or a surfboard or a mountain bike or whatever, or whether you're playing with your kids or having a conversation with your partner, a friend. It really flow manifests in all types of different settings. We all know the feeling. It's like I said, where we feel most alive, where we\n\nCole Heilborn (00:00:29): Feel our best. Welcome to the Backcountry Marketing Podcast. My name is Cole Holborn and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. Today's guest, his name is Jeremy Jensen. He's the founder of the Crux Academy of Out Wild. He's the host of the Adventure Entrepreneur Podcast, and he's a certified flow professional at the Flow Research collective. Jeremy, how are you doing?\n\nJeremy Jensen (00:01:21): I'm great, Cole. Thanks for having me, man.\n\nCole Heilborn (00:01:23): Yeah, thanks for being on the show. I feel like podcasts are one of the things that you find yourself doing a lot of. This is probably a pretty comfortable seat for you, huh?\n\nJeremy Jensen (00:01:35): Yeah, it is. It's something I love to do. I'm usually on the other end. I'm sitting in the other seat there. But yeah, it's certainly been a guest time or two as well. And yeah, I think it's an awesome format to dive deep into some cool topics.", "token_estimate": 479, "speakers": ["Jeremy Jensen", "Cole Heilborn"], "start_timestamp": "00:00:03", "end_timestamp": "00:01:35", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "afd25b27-5b8c-467d-ba5e-4fb7ad2a391b", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 1, "content": "Cole Heilborn (00:01:50): A hundred percent. We're going to dive really deep into a couple topics today. We're going to talk about Flow State, what it is, what it isn't really what it does, and why we as marketers or just anyone in the outdoor industry should be cognizant of this thing called Flow State. We're going to get kind of gritty into that in a moment, but Jeremy, I'd love if you could give us a quick introduction. Your background, obviously you do a bunch of different things, so could you put it all out on the table for us?", "token_estimate": 135, "speakers": ["Cole Heilborn"], "start_timestamp": "00:01:50", "end_timestamp": "00:01:50", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "8ecd930a-b1f5-41c8-ab07-773e9a2b323d", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 2, "content": "Jeremy Jensen (00:02:20): Absolutely. Well, I'll make it the short version first, and if we want to go deeper we can. But yeah, long story short, just my outdoor resume, so to speak, and career. Grew up in Salt Lake City and was a very active outdoor enthusiast user, big skier, mountain biker growing up that's not really changed and worked in the outdoor industry for various companies in my early twenties and ended up just being very nomadic through most of my twenties, a lot of international travel and kind of nomadic tendencies. And anyway, ended up in about 30 or so thinking maybe where am I going? What am I doing with my life? So I ended up back in school. I ended up in graduate school back east and in the DC area. That landed me into consulting. I did an MBA out there. It landed me into consulting for a while, which was great. (00:03:24): Really, really cool career. Met a lot of really smart people and did a lot of cool work, but ultimately I knew that wasn't kind of what I was looking for and made me feel alive. We'll talk more about that later. That is flow. But yeah, and I actually just read a few books and I knew I wanted to do something different and realized I didn't know exactly what that would be. So I knew I wanted to get back into the outdoor space, and I'll never forget, I was in Utah at the time, visiting my parents for Christmas holidays. I was up at Snowbird and skiing one day and just had this epiphany. I was like, Hey, maybe a podcast would be interesting to dive into. So committed that to that, made it happen, came home. I was like, okay, I committed. Now what do I do? (00:04:12): You can relate to that call. So anyway, long story short, that kind of set me on a trajectory. And so I met my business partner in Out Wild Sonny, I should say now. She just got married this last year to Alex, and yeah, so that's been a really cool business for us out wild. It's basically a retreat business where we take people outside for three or four days into a pretty inspiring location, go climbing, mountain biking, whitewater rafting, and then we try to be thoughtful about how to create a more intentional lifestyle, a more outdoor driven lifestyle. So we do a lot of workshops and that type of thing. I teach Flow workshops at those events is a coach. She does a lot of work around mindset and aligning your values to your interests and your career, that type of thing. So that's a really cool business. (00:05:08): And then again, out of that really saw a need between the podcast and Out Wild for breaking down this barrier that is basically accessibility into the outdoor space. Let's face it, it can be kind of an intimidating space in some ways, especially if you're new to it. And so I just started to really become more interested in accessibility, inclusion, education, community building, and so yeah, that's how Crux Academy came about. That's my newest business. That's been going about a year. We've had great initial traction with that. The model there is basically, it's kind of like masterclass, but for the outdoor adventure, active lifestyle space. So very high end, high quality online courses across the space. So we don't just focus on things like backcountry skiing and fly fishing and trail running. We have courses and all those, but we think more broadly as we're doing a climate activism course with Protect our winners, for instance, we're doing a DEI course with the American Alpine Club or so of course on Van Life actually when we're producing right now. So it's been a fun journey. That's kind of the synopsis, but that's kind of where I'm sitting and kind of how I got to where I am.", "token_estimate": 914, "speakers": ["Jeremy Jensen"], "start_timestamp": "00:02:20", "end_timestamp": "00:02:20", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "2c4bafc6-fbe2-4513-873b-cfe6001a0a52", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 3, "content": "Cole Heilborn (00:06:32): Awesome. Awesome. Well, thanks for breaking that down. I was poking around on Crux Academy earlier this week or the week before, and I started fly fishing two years ago, and I'm trying to figure it out. And I've had some really great fly fishermen fly Fisher women on the podcast in episodes past, and I'm always like, I want to learn all the things that, and I saw you guys had some awesome classes, it looks like on Crux Academy that talk just about that stuff. So I might have to look into that a little more seriously here as I'm hunkering down for the winter, but it looks pretty cool.\n\nJeremy Jensen (00:07:07): Yeah, thanks man. Yeah, that course is actually, believe it or not, most popular course, Maddie Brennaman a badass. She's a great angler. She's a guide in Steamboat out of Steamboat, Colorado, and she did a fantastic job. And you're right, there's so much nuance to fly fishing and understanding the life cycles of all the flies and the midges and all of this. I myself have fished for a while. I learned a lot from that course. So yeah, hit me up, Cole. We'll get you squared away on if you want to take that course.\n\nCole Heilborn (00:07:39): Sweet. Sounds good. So I'm curious, you alluded to this in your intro, but when were you first introduced to the idea of flow?", "token_estimate": 329, "speakers": ["Cole Heilborn", "Jeremy Jensen"], "start_timestamp": "00:06:32", "end_timestamp": "00:07:39", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "86b9e97d-a7c9-4285-81b6-2726d1a9fd90", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 4, "content": "Jeremy Jensen (00:07:48): Well, actually I mentioned a couple books that I read while I was a consultant, and while I was kind of navigating a transition, that was my introduction, I always knew that's kind of interesting. And I think a lot of people that listen to this show probably relate to this, but flow, we love it, we know it. We just dunno how to articulate it, and we certainly don't know the neuroscience that underpins it. So I think that's one thing I want to make really clear is I always was sort of subscribed to it, if that makes sense. I love the action sports. I love a lot of these things that I think drive flow. So I read a book called Stealing Fire by Steven Kotler, who actually ended up being my mentor and who I work with at the Flow Research collective. He's a very prolific author on peak performance, optimal states of consciousness flow states, that type of thing. (00:08:42): That book was very good, highly recommended. It was a Pulitzer nominee, New York Times bestseller, all of that. But that just really opened up my eyes. I was like, holy shit, wow. Steven is really articulating this sort of feeling that I've always been drawn to. And so that was sort of my introduction to it. And that was actually thanks to a guy I had on my podcast, Frank Scotty, he runs an adventure travel company nomad in out of Carbondale, Colorado. He recommended that book and I was like, wow, great recommendation. Thanks for that. Because kind of changed my trajectory in some ways. I got re-involved with Steven and now I work pretty closely with him.\n\nCole Heilborn (00:09:22): Gotcha. And you mentioned something interesting that a lot of people can probably relate to flow, but maybe they don't understand what it is, or even though the word flow that's associated with the feeling, what is flow or what are some other words that people might use to describe this idea of flow?", "token_estimate": 475, "speakers": ["Jeremy Jensen", "Cole Heilborn"], "start_timestamp": "00:07:48", "end_timestamp": "00:09:22", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "c54fb71f-19eb-4ae4-bcd8-b3ca185d9049", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 5, "content": "Jeremy Jensen (00:09:38): Absolutely. Yeah. So believe it or not, there's a pretty technical definition that isn't even that technical. It's very simple actually, but this is the official definition. There's a guy actually just passed away, Hungarian American psychologist by the name of Miha Chi sent Miha very difficult name, but he's sort of the godfather of positive psychology of flow. He defined flow as it's a optimal state of consciousness where we feel our best and we perform our best. So pretty simple. That's a really good, I think, tangible definition, but I like to take it a little step further and just say, I mean, come on. It's when we feel the most alive, this is what makes life worth living. These are some of the most meaningful moments in our lives, whether you're on a snowboard or a surfboard or a mountain bike or whatever, or whether you're playing with your kids or having a conversation with your partner or a friend. (00:10:37): It really flow manifests in all types of different settings. We all know the feeling. It's where, like I said, where we feel most alive, where we feel our best, where we're highly motivated, time sometimes slows down or speeds up. We have uber sense of clarity. There's a lot going on in the brain and I'm happy to dive into that. But at the end of the day, that's what we're talking about. So I'm really compelled by it because let's face it, it's the coolest feeling there is. And so why not harness it more effectively? And that's the work that I do, and that's instead the work that Steven does is try to help people take it from something that's very fleeting, that's just randomly showing up out there in random experiences that we're having, but very much being prescriptive about it. But how do we actually make it more consistent, more reliable, almost on demand? And the science has advanced far enough now that we know what's going on in the brain and how the neurochemistry works.\n\nCole Heilborn (00:11:37): Interesting. So I feel like before I knew of the word flow, what I would always describe what I have now learned is flow is like you're in the zone or you're just\n\nJeremy Jensen (00:11:45): Totally", "token_estimate": 544, "speakers": ["Jeremy Jensen", "Cole Heilborn"], "start_timestamp": "00:09:38", "end_timestamp": "00:11:45", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "f52dd3f2-e27e-461e-b340-37dd9b719096", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 6, "content": "Cole Heilborn (00:11:46): Your head's down and you're just going and making stuff happen.\n\nJeremy Jensen (00:11:50): Yep. That's the exact same thing in the zone. Vibing, jazz musicians call it in the pocket. There's lots of different types of labels for it, but that's exactly the same thing.\n\nCole Heilborn (00:12:05): And indie, outdoor adventure athlete world, I got to assume a lot of folks probably experience this as they're out adventuring or doing whatever physical activity they enjoy doing. And I think you could probably speak to this, but flow is something that athletes are super aware of and are figuring out ways to utilize as they're performing their athletic feats.\n\nJeremy Jensen (00:12:30): That's right. Yep, exactly. I think one of the other common ways to describe flow is runner's high. So runners specifically tend to really experience this because it's actually a fairly simple activity to do. And if you have a certain amount of fitness, you can do it for a while, and after about five or 10 minutes you enter this sort of really meditative space, and that's kind of flow at work. So yes, there's a high physiological component to flow. Often we're trying to drive the neurochemistry flow into the brain, and what activity does is kind of takes us out of our minds and into our bodies. And that tends to be very, it's the same thing in we do in meditation. That's what meditation is. It's kind of focusing on one thing, the breath, and if you can, because flow one main characteristic is it's what drives your attention into the present moment. So one thing, you cannot be distracted or multitasking beyond more than two things at once largely and still have a profound flow state, for instance. So athletes tend to have a very good experience with this because there's that mind body component.\n\nCole Heilborn (00:13:50): Interesting. You mentioned that the science as of recently has reached a point where we can understand more of what's going on inside of our brains in flow state. What have we been learning? What do we now know?", "token_estimate": 516, "speakers": ["Cole Heilborn", "Jeremy Jensen"], "start_timestamp": "00:11:46", "end_timestamp": "00:13:50", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "31a995a2-bb8d-493f-a572-e8f83125efb4", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 7, "content": "Jeremy Jensen (00:14:03): Yeah, I love this question. Well, how much time do you have basically, but I can summarize it. Long story short, is that, so e eek G machines, FMRI machines, so brain scanners, neuro electric devices, tell us a whole lot about what's going on in the brain in general across a lot of types of disciplines and neuroscience in general. Now, there has been a lot of activity and energy around flow recently, well, relatively recently, because a lot of big organizations are waking up to its potential. So you have, for instance, the Navy Seals are very well-known. The Department of Defense in particular has pumped a lot money into this space and into the research side of things because they found that their special ops forces can actually operate at a much higher level when they're leveraging flow states. For instance, academic institutions, universities are putting a lot of money into this as well. (00:15:10): On top of that, a lot of the private sector as well. So you see Deloitte's leading a big study, a lot of the top tech companies, Google is very active in this space because it has a lot of implications for productivity, motivation, output, employee engagement, that type of thing. So that's why we're seeing a big push in this. And so to answer your question, it's kind of a blend of it's well-funded, the research, and then we have the capability to understand what's going on. So one quick example that I think will help people conceptualize what I'm talking about. And so one of the main characteristics of flow from a anatomical perspective is that there's part of our brain up here front behind our forehead called the prefrontal cortex. So it's actually one of the younger parts of the brain, relatively speaking. And this is a lot of our highly analytical cognitive functioning. (00:16:12): So things like self-doubt over analysis, a lot of the higher end social capabilities and nuances from our social interactions are also housed there. And so why that's important is because it's been shown through FMRI that the prefrontal cortex actually slows down in flow. And so what this means is that we become less analytical, we become less in our own brains and and all the things that we all experience all the time. And so we call that transient hypofrontality. It just means that that front of the brain is slowing down, going offline. And so it allows us to be more present in the moment. We're not constantly judging what's going on in that moment. Let's use surfing. You're not constantly seeing how you're looking to someone else on a surfboard. You're in the moment, you're actually, you've got survive. Maybe it's a big wave. Maybe you have to execute this move or else there are serious consequences. This is flow at work. So that's just one example of what the science is starting to tell us and what we're starting to understand.", "token_estimate": 722, "speakers": ["Jeremy Jensen"], "start_timestamp": "00:14:03", "end_timestamp": "00:14:03", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "6dc48f0f-17fe-479e-8004-45cbd92fad0f", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 8, "content": "Cole Heilborn (00:17:34): Gotcha. So you made the connection between I think why we're having this conversation and why it's of interest to marketers and really anyone in the professional who has a job frankly and wants to just do things, it increases productivity. We're going to get into that part of it in a bit, but I'm curious if we can talk a little bit more about the triggers of flow. What gets you into this mindset? And I think you said there's kind of four categories, and then within those categories there's multiple types of triggers.\n\nJeremy Jensen (00:18:06): Yeah, yeah. There's a couple with different ways to slice this. People sometimes categorize them. I know when I think about this, I do like to categorize them into environmental versus group flow. For instance, there's group flow triggers, there's individual triggers. So if you think of a music concert where you're all listening to the same music, the same band, you're all in it together and you have this, I think we've all had those experiences of a magical moment at a music concert or the like. That's a great group flow example. And then you have more of the individual where you're reading a book and you're inspired and you have this spike of dopamine or something like that. Yeah. But generally speaking, there's 22 known drivers or triggers of flow. And we do a lot of work around this because the more you understand the triggers, the more you're able to leverage those triggers effectively in your day-to-day life.\n\nCole Heilborn (00:19:02): And what are some of the more common triggers that folks might come across in their day-to-day?", "token_estimate": 407, "speakers": ["Cole Heilborn", "Jeremy Jensen"], "start_timestamp": "00:17:34", "end_timestamp": "00:19:02", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "32cece79-edaa-4310-821a-da5a19fb2e9e", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 9, "content": "Jeremy Jensen (00:19:08): Absolutely. Well, a lot of the common ones, first of all, let's call one out that we all know very well, but that maybe isn't the most productive source of dopamine, and that is social media. You hear a lot about this, but the reason why social media spikes dopamine is predominantly because of novelty. The reason why we scroll and we're always wanting to see the next new thing is because novelty is one of the biggest, most potent flow triggers. And so you're getting dopamine norepinephrine, pumped into the brain and it feels good. We get a little spike of it. So that's one example that we all know. So novelty is one big flow trigger. There's things like complexity. So typically when there's things that are really complex in nature, that's also a good flow trigger clear goals. So establishing a very simple clear goal and then working towards that goal and reaching it also a good way to prime the neurochemistry. (00:20:09): You have things like curiosity that also if you think about times you've been truly curious, that you tend to have a very motivated, elevated sense of state. That's a big one. One of my favorite ones, just to give people a sense, is called the challenge skills balance. And basically this is just a concept where if you have a task or an activity that is not so hard that it gives you anxiety and that you can't do it and not so easy that it makes you bored, this tends to drive dopamine really effectively. Classic example is if you have a deadline, and let's say we've all procrastinated, we've all waited till the last minute to do something, well, you freak out, you freak out, you freak out, and then with an hour left, you're like, okay, I got to do this. I have no other options. Well, you tend to be very productive during that time. That's not a coincidence. That's the challenge skills balance at work. You're elevating the challenge that you need to get that thing done, and you're elevating the level of skill that it takes to get it done as well. So that's a very powerful one.\n\nCole Heilborn (00:21:26): How long have we known about flow? How long has science known about this idea?", "token_estimate": 540, "speakers": ["Jeremy Jensen", "Cole Heilborn"], "start_timestamp": "00:19:08", "end_timestamp": "00:21:26", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "a14e6cd4-08fa-4b9c-847c-848712828675", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 10, "content": "Jeremy Jensen (00:21:32): Well, it's a great question. I think conceptually, we've known about it for thousands of years. I think you have seed in the literature very early on. Now, there's a big historical of study on this, and actually Steven Kotler's the one that has done a lot of work around this. He's a big history buff, kind of starting with Nietzsche Nietzche is one of the ones that really was popularized with describing the state. William James is also another big one. He was a big student of psychology. So Flo really comes from the study of psychology and specifically positive psychology. So I don't think there's a true root to it. Certainly we've only been able to look into the brain and know what's going on for the last half a century or so at the most and really significantly and in a detailed way probably within the last 20 years. So yeah, you're looking at a lot of the understanding we have as very modern.\n\nCole Heilborn (00:22:38): Gotcha. So there's these 22 triggers that can be used to induce flow. I guess when I was first kind of researching this topic, I thought it was, or when I think about the experience of flow, I think it just happens. There's no way to encourage it, there's no way to create it. It's an environmental related thing. But it sounds like now that these triggers have been identified, you can kind of hack your way into flow.", "token_estimate": 345, "speakers": ["Jeremy Jensen", "Cole Heilborn"], "start_timestamp": "00:21:32", "end_timestamp": "00:22:38", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "a66ac574-1fa9-4daf-9706-4cbe835018e1", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 11, "content": "Jeremy Jensen (00:23:07): That's right. Exactly. And that's the power of it. And so when we talk about people who are marketers or professionals or videographers, you name it, it doesn't really matter which space you're in, you can leverage these triggers to your advantage. So lemme just use that example that I used before. So a lot of the work we do at the Flow Research collective and just the work I do in general, it's helping people understand. And I used it myself. Let me be very clear. I'm a good test case because I've become very passionate about it and tried to educate myself on deep level. And so I've implemented a lot of this, and frankly, that's taken my productivity through the roof. But to use that example of the challenge skills, balance and that sort of deadline where we're procrastinating, where we're up against a deadline, this is a very tangible example, but I think it's very salient. (00:24:05): So let's say we've all heard of gamification. There's sort of an element of that in here. So for that particular trigger, one strategy is to say, okay, Cole, you've got this deadline for a client. You're producing some content, you got to get the post postproduction done. It's due by noon on Monday. All right? Yeah, if you procrastinate, you're going to wait until then and then you're going to have it work that way. But let's say you still have a week left, well give yourself an hour to do some particular task on the post-production, but instead of giving yourself an hour, give yourself 30 minutes, manufacture some type of constraint where, because when we talk about the challenge skills balance, think of it as an XY access. If you increase the challenge, you're going to drive dopamine. If you decrease the time that it takes to do the thing, you're going to have to be more focused and you're going to be more successful and get it done. (00:25:05): So that's one example I use almost every morning when I think about my most important tasks for the day, I think, okay, realistically, how long will this take me to do this task? Sometimes it's a big task, two hours, no, I'm going to try for an hour. I'm going to set a timer, the omoro technique, and I'm going to really try to, everything else aside, environment is really important. You can't have distractions, you can't have your phone, you can't have your dog coming up to you. Really, you got to focus. No bullshit. And so that tends to be very effective. So that's just one small example of the way people can apply this. But yeah, we know enough now that you can absolutely. Risk is another a perfect. Another example for flow, of course, actions, sports athletes know this very well because we're constantly putting ourselves at risk, bodily harm if we screw up the thing. (00:26:01): So that drives flow. And that's actually one of the reasons why action sports is so good at it. But you can apply that to all types of different tasks. So it could be all types of different ways that you can build in novelty and risk and challenge and clear goals and a lot of these different triggers in an effective way throughout your day. And you want to prime flow early in the morning because one thing that's always set out in the space is the more flow you get, the more flow you get. And it's so true because if you can start to prime it early in the day, you tend to ride a wave throughout a good chunk of the morning and even through the day. I know that from personal experience.", "token_estimate": 869, "speakers": ["Jeremy Jensen"], "start_timestamp": "00:23:07", "end_timestamp": "00:23:07", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "876b4cb1-779c-4cc5-b0f2-dc7b78d5c43b", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 12, "content": "Cole Heilborn (00:26:44): So in a situation like you described where you are creating an artificial deadline that's earlier than maybe the outside deadline, even though you are the one that's creating that deadline, you can still trick yourself. I maybe trick isn't the right word.\n\nJeremy Jensen (00:27:01): That's the right phrasing. You're tricking, it's gamification. But see, our brains react to that, right? I mean, you got to believe it. You can't just be like, oh, well if I don't do it in an hour or so, what you got to really try? That's the difference. So as long as you can do that and just say, okay, make it a challenge, it's gamifying. It's like, can I do this right? And again, that's just one small example. There's a lot of different ways, but in that case, yeah, that's exactly what you're doing. You're fooling yourself, but it's effective.\n\nCole Heilborn (00:27:30): And is it like exercise where the more you do the thing, the easier it is?", "token_estimate": 241, "speakers": ["Cole Heilborn", "Jeremy Jensen"], "start_timestamp": "00:26:44", "end_timestamp": "00:27:30", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "517c864d-ad91-4fe7-9350-56ca357e9e7f", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 13, "content": "Jeremy Jensen (00:27:38): Yes, exactly. The more flow you get, the more flow you get. So when you're prying the system, when literally your brain knows how to usher the neurochemistry into the brain and does so routinely, it tends to happen a lot quicker. And this is actually a good segue if you're interested to go into another layer of this, and that is the flow cycle. So every flow state has a four stage cycle, and it turns out we can really hack the cycle. There's two phases that in particular we can really optimize. So it starts with a struggle phase. You go into a release phase, you go into the flow experience itself, and then you have a recovery phase. So that's the four stages of flow. Think about it. Let's use a runner example again just to make this really concrete for people. So we've all tried to go on a run or do some type of physical activity, and we're on the couch, we're feeling lazy. (00:28:40): We have to go get our shoes, we have to get our clothes, we have to step out the door. That's often the hardest part, just getting going. That's the struggle phase. And if you think about it, anything worthwhile or most things worthwhile have a struggle phase, including all flow states. You have to push through something in order to get to the next good place. And from a neurochemical perspective, that's literally the case, right? You're going to start to get low, low dosage of dopamine anandamide into the brain during the struggle phase. Then you push through it. So you're out the door, you start walking, okay, you don't feel great quite yet, but you're at least moving the blood's flowing, okay, now you're in the release phase. Now you're starting to get higher levels of the neurochemistry. And then you start running, you've been running for five or 10 minutes, and you feel like you're running on air or water and you feel like a million bucks, right? That's the flow experience. That's the at work. You typically have four or five different neurochemicals pumping in at the same time. So it's like a stacked approach. And then of course you stop running or you get tired and then you have to recover. So it turns out the struggle and the recovery phase, we can actually heavily shorten those phases. And why that's important is because to your point, you can get into flow more regularly, more consistently, and with less effort once you understand how it all works, if that makes sense.", "token_estimate": 607, "speakers": ["Jeremy Jensen"], "start_timestamp": "00:27:38", "end_timestamp": "00:27:38", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "386d6385-5b53-4f02-b041-1486cc18ced5", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 14, "content": "Cole Heilborn (00:30:15): So if I don't, I'm going out for a run and I don't have the struggle to get off the couch. If I just, shoes are on, I'm out the door and away I go, am I going to have the same type of flow or the same runner's high? If I don't go through that struggle,\n\nJeremy Jensen (00:30:32): You'll still go through it. What you're trying to do is minimize the struggle so that it's easier to get through. So you would maybe put your shoes right by the door, you'd have your clothes laid out the night before so that you don't have to choose what color shorts you're going to wear, or there there's no clean t-shirt or whatever it is. These barriers, we want to minimize the barriers. And of course also psychologically knowing that the shoes are ready to go, that the shorts and everything is ready to go, and that you're cognizant of the fact that you know the reason why you're being lazy is because you just are being lazy. That's exactly it. You know that you just need to push through it, and you're going to have an amazing experience. That alone will be motivation in itself. So that's what we mean by sort of optimizing the struggle. You're still going to go through it. You still have to do the sort of boring stuff to get to the good stuff. You always will, but you can minimize it. You can minimize the barriers or the resistance to it and make it more efficient.\n\nCole Heilborn (00:31:38): So in the recovery stage, how important are things like food and rest or sleep to continued flow day after day?", "token_estimate": 382, "speakers": ["Cole Heilborn", "Jeremy Jensen"], "start_timestamp": "00:30:15", "end_timestamp": "00:31:38", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "c3a7232e-8453-4358-aabc-7d3d8bf3cc05", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 15, "content": "Jeremy Jensen (00:31:50): Well, endlessly important, and I'm not a scientist, I'm not a nutritionist, but at a high level, they're massively important. Active recovery specifically is the best thing you can do for yourself. And what I mean by active recovery is not sitting on the couch eating potato chip and watching a show, even though it's okay to do that, right? Let's be clear, we all do it and we should. But when we can, doing things like going for a walk with our partner or taking the dog out or playing an instrument or reading a book, something that's active, not just physically, but also mentally, that will help us sort of process and recover more effectively so that we can get into that next flow quicker and that we can actually allow our system the chance to regenerate reprime, dopamine stores and that type of thing.\n\nCole Heilborn (00:32:50): Gotcha. So all of this sounds great from the athlete's perspective, you're going to run faster, run farther, feel better. You mentioned though that companies like Facebook and Google and even the Navy Seals are researching and trying to figure out how to utilize flow. What is the business world or the military seeing in flow, and what are the productivity results or implications?", "token_estimate": 312, "speakers": ["Jeremy Jensen", "Cole Heilborn"], "start_timestamp": "00:31:50", "end_timestamp": "00:32:50", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "1d502aa4-d9f7-42f0-aded-c5612039a961", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 16, "content": "Jeremy Jensen (00:33:18): Yeah, great question. Well, the results are, they're a little bit of a mixed bag, but generally speaking, there's a lot of, well, I say famous studies, I don't know if an average person knows about them, but if you're in this space about them, for instance, McKenzie, the very well known consulting firm, did a very robust study on flow and the relationship to productivity amongst executives. And they found that the executives that were experiencing more flow than their peers we're seeing upwards of 500% increase in productivity. So that's pretty massive. There's some studies out of the University of Sydney, USC, there's new stuff coming out all the time. So the results and the sort of output are there. Basically you see massive increases in productivity, motivation, clarity, focus, and sense of fulfillment and happiness. Actually, the biggest speaking of research, the biggest study ever run in this psychology world was done by, and it actually started out as a study on happiness. (00:34:36): And that's actually how he discovered flow is by interviewing what he called the happiest people on the planet. And so they've interviewed tens of thousands of people at this point. It's an ongoing study, and that's exactly the conclusion they made, is the people with the most flow in their lives are the happiest people on the planet. Yeah. So why is it important for companies, for the military, that type of thing. Lemme start with companies. The military is a little bit of a specific case, but companies, if you think about it, obviously the more productive, motivated, that type of thing employees are, the better they'll be at their jobs and actually the more fulfilled they're going to be as well. And that's really what it comes down to. That's why you see people working on employee engagement specifically, really looking at this area and saying, wow, okay, this has some major implications for wellness and wellbeing and that type of thing in the workplace. (00:35:38): And the best way to describe that is there's a big movement towards helping people move into roles, spending more of their time at work in roles that they are inclined to get some type of enjoyment out of. So the example I like to use is spreadsheets. I hate spreadsheets, I despise them, but some people love them. Some people really enter a flow state. You may be one of those people call. So that's one good example is like if that's the type of person you should be in a data type role, you should do more data. We're all going to have tasks that we don't like to do. And there's tricks, like I said, that Pomodoro technique that will help you in those types of situations. But yeah, we want to do the tasks that really bring us alive. And so that's one example. But yeah, it's largely productivity is the reason why companies are getting behind this. And the other reason why the tech space is embracing it. So ubiquitously is of course coding. You're in that flow, you're in that zone quite a bit. Most coders have been in this space, and frankly, a lot of people get into coding because they can drop in, it requires a deep amount of concentration, and they can spend five hours coding and it feels like five minutes. That's the classic flow description.", "token_estimate": 819, "speakers": ["Jeremy Jensen"], "start_timestamp": "00:33:18", "end_timestamp": "00:33:18", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "2c25b95b-a9f9-4f32-8364-38fe7df766a7", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 17, "content": "Cole Heilborn (00:37:06): So what are we seeing at these companies who are investing in flow? Is it different management practices? Is it training for employees? Is it things like changing workspaces or what are all the different ways that you can actually implement some of these ideas or try to\n\nJeremy Jensen (00:37:25): All the above. Everything you just mentioned starting from the back one, there's some really cool concepts out there about how you design an environment. So it turns out incorporations in the last 15 years, people have moved towards these open floor plans where everyone can see each other, they're with each other. Turns out that's actually not good. We don't want that. That's actually, we want more seclusion from, we want the ability to go out and interact and have conversations with our comrades, but we actually want, and that's why a lot of people work with headphones now. And actually we should talk about music. Music is a huge driver of flow, specifically Ural beats, but the open flam floor space is not a good environment. And so basically the more you can focus, that's the big Cal Newport who's a great author in this space of distraction and digital minimalism and that type of thing worth checking out. (00:38:30): He talks a lot about this idea of focus is the superpower of the 21st century. Think about it. We are all walking around with so many things coming at us or in our brain, what we call cognitive load. We're all just overstimulated to the max. And so the degree to which we can actually focus is going to determine how much deep work or good work that we do. Otherwise we're just moving in a shallow way between tasks and we're not actually doing anything. What are we doing? Responding to a couple emails or whatever. So in the creativity spaces, like writing, videography, some of those areas, yeah, that's critical. If you can't focus, you're screwed, right? You can't do the thing. So anyway, that's kind of important. The environment side management practices, designing workplaces and helping people redesign development plans that are more aligned to principles that are behind flow much more effective than some of these more arbitrary things that we're shooting for. (00:39:43): People are driven and motivated in different ways. It's not all about getting the promotion or whatever. It's about going to work and feeling enlivened, right? We got to create an environment for that, and obviously management plays a role in that. So yeah, there's a lot of different things you can do, but you really nailed a lot of the big ones, and it's really redesigning the work environment so that we're leveraging neurochemistry more effectively. Namely, we got to get away from things like Slack email and just massive amounts of distraction. That's probably the biggest thing that companies can do is minimize distraction for employees because it's so out of whack right now. There's some really cool studies out there, but there's been some done that people spend maybe 35 minutes all day actually focused out of an eight hour workday. This is ridiculous. You know what I mean? Again, we have the open floor plan, we have the people walking by and we have the people coming up, how was your weekend? I mean, that stuff's all great and good, but we need to go into our little cave, so to speak, and get the work done. So anyway,", "token_estimate": 846, "speakers": ["Cole Heilborn", "Jeremy Jensen"], "start_timestamp": "00:37:06", "end_timestamp": "00:37:25", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}, {"id": "db3bdb0b-3d2a-464c-aaac-e69b57954c97", "episode_id": "18b72ad2-a704-465a-a508-3c4a813cc45d", "cms_item_id": "68225dfc7bb476527f8c487d", "chunk_index": 18, "content": "Cole Heilborn (00:41:00): So I think about the creative space and the push to have open floor offices because you get that ping pong water cooler bouncing ideas off of each other type of environment. But I think you sent over a resource that I was reading and it said creativity can be increased almost 400% in a flow state. Is it a balance of having the open floor plan and the comradery aspect and then also having places where you can go and hibernate and focus and do deep work?\n\nJeremy Jensen (00:41:35): Yes, sort of. Yeah. Very important distinction. Thank you for that, Cole. Yeah, I'm not saying at all that you only have to be a hermit and you have to just go into your little cave function in there, right? That's not at all what I'm saying. I'm saying that's actually a really effective way to become creative. But if you talk about creativity in particular, that's actually going to be way more effective with a group. But the difference is that it has to be intentional ideation time with a group that's structured, that has a goal, that has some boundaries around it, not this open floor plan that's just a random, you just happen to be listening to someone's weekend plans. That's distracting when you're trying to be creative. But if you take yourself and put five people in a room, or you're in an open floor plan and you're all focused on the same goal and you're contributing ideas and doing, one of the most popular flow triggers in the group side of things is yes and right. (00:42:42): This is what drives improv groups. When you're doing improv acting, this is usually how they get you going is you do a little line and then you say yes, and you add to it, you iterate onto, and that's the same idea that drives flow really effectively. It's the same idea in a group ideation session. You want to add ideas and some of the best ideas, and definitely some of the top companies utilize those types of settings. So I want to be a really clear distinction. It's this meaningless distraction that you don't want, but you do want structured group time for creativity.", "token_estimate": 522, "speakers": ["Cole Heilborn", "Jeremy Jensen"], "start_timestamp": "00:41:00", "end_timestamp": "00:41:35", "podcast_index": 83, "episode_name": "Ep 83: Jeremy Jensen | Using Flow State to Improve Creativity and Productivity | Crux Academy", "slug": "ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "web_url": "https://www.portsidepro.com/podcast-feed/ep-83-jeremy-jensen-using-flow-state-to-improve-creativity-and-productivity-crux-academy", "guest_name": null, "guest_title": null, "categories": [], "short_description": "In 2021 the most valuable commodity is attention. As marketers, we all seek to earn the attention of our audience. But how often do we consider our own focus while on the job? Are those trips to the water cooler really helping your creativity? Does keeping your email tab open or closed help or hinder communication?", "podcast_length": "44:105"}]
